window.FAQ=(window.FAQ||[]).concat([
 {id:'cpx-001',thema:'compliance',vraag:'Wat is het verschil tussen adviseren en bemiddelen onder de Wft?',antwoord:`Adviseren is het doen van een persoonlijke aanbeveling over een financieel product aan een specifieke klant. Bemiddelen is het werkzaamheden verrichten gericht op het tot stand brengen van een overeenkomst tussen klant en aanbieder. Veel adviseurs doen beide. Controleer of uw vergunning beide diensten en de juiste productcategorieën dekt.`,tags:['Wft','adviseren','bemiddelen','vergunning'],bron:'Wft'},
 {id:'cpx-002',thema:'compliance',vraag:'Welke productcategorieën moet mijn AFM-vergunning dekken?',antwoord:`Uw vergunning moet elke productcategorie dekken waarover u adviseert of bemiddelt. Denk aan hypothecair krediet, consumptief krediet, schadeverzekeringen, levensverzekeringen, inkomensverzekeringen en betaalrekeningen. Adviseert u buiten uw vergunning, dan handelt u zonder vergunning. Controleer bij uitbreiding van de dienstverlening eerst het AFM-register.`,tags:['vergunning','AFM','productcategorie'],bron:'AFM'},
 {id:'cpx-003',thema:'compliance',vraag:'Mag ik een klant doorverwijzen naar een collega zonder eigen vergunning?',antwoord:`Alleen als die collega werkt onder de vergunning van een onderneming die wel een vergunning heeft, of als de doorverwijzing zelf geen advies of bemiddeling is. Een losse aanbrenger die alleen gegevens doorgeeft valt soms onder een uitzondering. Toets per situatie of er sprake is van advies of bemiddeling. Leg de samenwerkingsafspraken schriftelijk vast.`,tags:['doorverwijzen','vergunning','samenwerking'],bron:'Wft'},
 {id:'cpx-004',thema:'compliance',vraag:'Wat moet ik regelen bij een wijziging van dagelijks beleidsbepalers?',antwoord:`Een nieuwe dagelijks beleidsbepaler moet vooraf door de AFM worden getoetst op betrouwbaarheid en geschiktheid. Meld de voorgenomen benoeming tijdig bij de AFM. De persoon mag pas in functie na een positieve beoordeling. Bewaar de correspondentie in het bedrijfsdossier.`,tags:['beleidsbepaler','betrouwbaarheid','geschiktheid','AFM'],bron:'Wft'},
 {id:'cpx-005',thema:'compliance',vraag:'Welke wijzigingen meld ik aan de AFM?',antwoord:`Meld onder meer wijzigingen in beleidsbepalers, zeggenschap, rechtsvorm, adres en de productcategorieën waarin u actief bent. Ook het stoppen van werkzaamheden meldt u. Sommige wijzigingen vragen een melding vooraf, andere achteraf. Raadpleeg het AFM-portaal voor de actuele meldplichten en termijnen.`,tags:['AFM','meldplicht','wijzigingen'],bron:'AFM'},
 {id:'cpx-006',thema:'compliance',vraag:'Is een beroepsaansprakelijkheidsverzekering verplicht?',antwoord:`Ja. Een adviseur of bemiddelaar met een Wft-vergunning moet een beroepsaansprakelijkheidsverzekering hebben die voldoet aan de wettelijke eisen. De minimale dekking is wettelijk vastgelegd en kan worden aangepast. Controleer jaarlijks of uw polis nog aan de actuele eisen voldoet. Let ook op uitsluitingen en het verzekerd bedrag per aanspraak.`,tags:['BAV','aansprakelijkheid','vergunningseis'],bron:'Bgfo'},
 {id:'cpx-007',thema:'compliance',vraag:'Wat betekent integere bedrijfsvoering voor een adviesbedrijf?',antwoord:`U voorkomt dat uw onderneming of medewerkers betrokken raken bij strafbare feiten, belangenverstrengeling of handelingen die het vertrouwen in de onderneming schaden. Dat vraagt om beleid, procedures en een integriteitsrisicoanalyse. Ook een klein kantoor moet dit aantoonbaar inrichten. Evalueer de analyse periodiek.`,tags:['integriteit','bedrijfsvoering','SIRA'],bron:'Wft'},
 {id:'cpx-008',thema:'compliance',vraag:'Wat is een systematische integriteitsrisicoanalyse (SIRA)?',antwoord:`Een SIRA brengt in kaart welke integriteitsrisicos uw onderneming loopt. Denk aan witwassen, fraude, belangenconflicten en omkoping. Per risico beschrijft u kans, impact en beheersmaatregelen. Actualiseer de SIRA bij nieuwe diensten, klantgroepen of incidenten.`,tags:['SIRA','integriteit','risicoanalyse'],bron:'AFM'},
 {id:'cpx-009',thema:'compliance',vraag:'Hoe vaak moet ik het klantprofiel actualiseren?',antwoord:`De wet noemt geen vaste termijn. Bij elk nieuw adviesmoment moet het klantprofiel actueel zijn. Ook bij periodieke dienstverlening hoort een controle van de klantgegevens. Leg vast wanneer en hoe u het profiel hebt bijgewerkt.`,tags:['klantprofiel','actualiseren','nazorg'],bron:'Wft'},
 {id:'cpx-010',thema:'compliance',vraag:'Mag ik een klantprofiel van een collega-adviseur overnemen?',antwoord:`U mag gegevens gebruiken, maar u blijft zelf verantwoordelijk voor een volledig en actueel klantprofiel. Controleer de gegevens met de klant en vul ontbrekende onderdelen aan. Een overgenomen profiel zonder eigen verificatie is een veelgemaakte fout. Noteer welke gegevens u hebt gecontroleerd.`,tags:['klantprofiel','overdracht','verificatie'],bron:'Wft'},
 {id:'cpx-011',thema:'compliance',vraag:'Hoe ga ik om met tegenstrijdige doelstellingen van twee partners?',antwoord:`Breng de doelen van beide partners afzonderlijk in kaart. Bespreek waar ze botsen, bijvoorbeeld snel aflossen tegenover maximale bestedingsruimte. Zoek een gezamenlijke prioriteit en laat beide partners die bevestigen. Leg de afweging en de gemaakte keuze vast in het dossier.`,tags:['doelstellingen','partners','klantprofiel'],bron:'Wft'},
 {id:'cpx-012',thema:'compliance',vraag:'Moet ik de risicobereidheid per product apart vastleggen?',antwoord:`Risicobereidheid kan per doel verschillen. Een klant kan voorzichtig zijn met zijn woning en meer risico willen lopen met vermogensopbouw. Leg daarom de risicobereidheid vast per doel of productgroep. Een algemene score zonder koppeling aan het advies is onvoldoende.`,tags:['risicobereidheid','klantprofiel','doelen'],bron:'Wft'},
 {id:'cpx-013',thema:'compliance',vraag:'Wat is het verschil tussen risicobereidheid en risicodraagvermogen?',antwoord:`Risicobereidheid is hoeveel risico de klant wil lopen. Risicodraagvermogen is hoeveel risico de klant financieel kan dragen. Een klant kan veel willen maar weinig kunnen dragen. Het advies houdt rekening met de laagste van beide. Leg beide vast en motiveer de keuze.`,tags:['risicobereidheid','risicodraagvermogen','passend advies'],bron:'Wft'},
 {id:'cpx-014',thema:'compliance',vraag:'Wat doe ik als de klant weigert inkomensgegevens te geven?',antwoord:`Zonder voldoende informatie kunt u geen passend advies geven. Leg de klant uit waarom de gegevens nodig zijn. Blijft de klant weigeren, dan adviseert u niet of beperkt u de dienstverlening tot wat wel verantwoord kan. Leg de weigering en uw reactie vast.`,tags:['klantprofiel','weigering','informatie'],bron:'Wft'},
 {id:'cpx-015',thema:'compliance',vraag:'Mag ik vertrouwen op mondelinge informatie van de klant?',antwoord:`U mag uitgaan van de juistheid van informatie van de klant, tenzij u weet of had moeten weten dat die onjuist is. Bij belangrijke gegevens zoals inkomen en verplichtingen vraagt u onderbouwing. Controleer onder meer het BKR en loonstroken. Leg vast welke stukken u hebt ingezien.`,tags:['klantgegevens','verificatie','onderbouwing'],bron:'Wft'},
 {id:'cpx-016',thema:'compliance',vraag:'Hoe toets ik kennis en ervaring bij een klant die zegt alles te weten?',antwoord:`Laat de klant de werking en risicos van het product in eigen woorden uitleggen. Stel gerichte vragen over eerdere producten en ervaringen. Een eigen inschatting van de klant is niet genoeg. Leg de antwoorden en uw conclusie vast.`,tags:['kennis en ervaring','toetsing','klantprofiel'],bron:'Wft'},
 {id:'cpx-017',thema:'compliance',vraag:'Wanneer is een advies passend?',antwoord:`Een advies is passend als het aansluit bij de financiële positie, kennis en ervaring, doelstellingen en risicobereidheid van de klant. Het advies moet ook haalbaar zijn op de lange termijn. Passend betekent niet de goedkoopste of de meest uitgebreide oplossing. De onderbouwing moet uit het dossier blijken.`,tags:['passend advies','klantprofiel','onderbouwing'],bron:'Wft'},
 {id:'cpx-018',thema:'compliance',vraag:'Mag ik een product adviseren dat de klant zelf al heeft gekozen?',antwoord:`Ja, als het product passend is. U toetst de keuze van de klant aan het klantprofiel. Is het product niet passend, dan zegt u dat duidelijk. Kiest de klant toch voor dat product, dan gaat het om afwijkend handelen en legt u dat vast.`,tags:['productkeuze','passend advies','klantwens'],bron:'Wft'},
 {id:'cpx-019',thema:'compliance',vraag:'Moet ik alternatieven in het adviesrapport opnemen?',antwoord:`Het is goed gebruik om te laten zien welke alternatieven u hebt overwogen en waarom u die niet adviseert. Dat maakt de afweging controleerbaar. Bij een klacht helpt dit om aan te tonen dat het advies zorgvuldig was. Beschrijf kort per alternatief de reden van afwijzing.`,tags:['adviesrapport','alternatieven','onderbouwing'],bron:'Wft'},
 {id:'cpx-020',thema:'compliance',vraag:'Hoe adviseer ik passend bij een klant met een wisselend inkomen?',antwoord:`Breng de inkomenshistorie in kaart over meerdere jaren. Volg de acceptatieregels van de geldverstrekker of verzekeraar voor het toetsinkomen. Bespreek wat er gebeurt in een slecht jaar en of er een buffer is. Leg de gekozen inkomensbasis en de risicobespreking vast.`,tags:['wisselend inkomen','passend advies','buffer'],bron:'Wft'},
 {id:'cpx-021',thema:'compliance',vraag:'Wat is het verschil tussen een orientatiegesprek en advies?',antwoord:`In een orientatiegesprek geeft u algemene informatie zonder persoonlijke aanbeveling. Zodra u een product of oplossing aanbeveelt voor deze klant, is er sprake van advies. Dan gelden alle eisen van passend advies. Let op: de grens is in de praktijk snel overschreden.`,tags:['orientatie','advies','grens'],bron:'Wft'},
 {id:'cpx-022',thema:'compliance',vraag:'Geldt de adviesnorm ook bij een advies via telefoon of video?',antwoord:`Ja. De wettelijke eisen zijn gelijk, ongeacht het kanaal. U moet het klantprofiel volledig vaststellen en het advies onderbouwen. Let extra op de identificatie van de klant en de vastlegging van het gesprek. Stuur de kern van het advies schriftelijk na.`,tags:['advies op afstand','video','adviesnorm'],bron:'Wft'},
 {id:'cpx-023',thema:'compliance',vraag:'Mag ik een volledig online adviestraject aanbieden?',antwoord:`Ja, geautomatiseerd advies is toegestaan. De zorgplicht en de eisen van passend advies gelden onverkort. De AFM verwacht dat de vragenlijst, de beslisregels en de controles goed zijn ingericht en getest. Zorg dat een klant kan doorschakelen naar een adviseur als de situatie complex is.`,tags:['online advies','robo-advies','zorgplicht'],bron:'AFM'},
 {id:'cpx-024',thema:'compliance',vraag:'Wie is verantwoordelijk bij een fout in de adviessoftware?',antwoord:`De adviseur en de onderneming blijven verantwoordelijk voor het advies. Software is een hulpmiddel. Controleer de uitkomsten op plausibiliteit en ken de beperkingen van het pakket. Leg afspraken met de softwareleverancier vast en meld fouten direct.`,tags:['adviessoftware','verantwoordelijkheid','controle'],bron:'Wft'},
 {id:'cpx-025',thema:'compliance',vraag:'Hoe adviseer ik een klant met beperkte digitale vaardigheden?',antwoord:`Pas uw werkwijze aan op de klant. Bied papieren stukken of een fysiek gesprek aan. Controleer of de klant de informatie echt begrijpt. Leg vast welke aanpassingen u hebt gedaan.`,tags:['kwetsbare klant','digitale vaardigheden','zorgplicht'],bron:'Wft'},
 {id:'cpx-026',thema:'compliance',vraag:'Wat doe ik bij twijfel over de wilsbekwaamheid van een oudere klant?',antwoord:`Ga niet zonder meer door met het advies. Vraag of er een gevolmachtigde of curator is en bespreek dit zorgvuldig. Betrek bij twijfel een vertrouwenspersoon of familielid met toestemming van de klant. Leg uw waarnemingen en stappen vast.`,tags:['wilsbekwaamheid','ouderen','kwetsbare klant'],bron:'Wft'},
 {id:'cpx-027',thema:'compliance',vraag:'Mag ik adviseren aan een gevolmachtigde namens de klant?',antwoord:`Ja, als de volmacht geldig is en de handeling dekt. Controleer de volmacht en de identiteit van de gevolmachtigde. Het klantprofiel gaat over de klant zelf, niet over de gevolmachtigde. Bewaar een kopie van de volmacht in het dossier.`,tags:['volmacht','gevolmachtigde','klantprofiel'],bron:'Wft'},
 {id:'cpx-028',thema:'compliance',vraag:'Hoe ga ik om met een bewind of curatele?',antwoord:`Bij beschermingsbewind beheert de bewindvoerder het vermogen. Bij curatele handelt de curator namens de klant. Voor sommige handelingen is toestemming van de kantonrechter nodig. Controleer de beschikking en leg vast wie bevoegd is.`,tags:['bewind','curatele','bevoegdheid'],bron:'Burgerlijk Wetboek'},
 {id:'cpx-029',thema:'compliance',vraag:'Moet ik een klant waarschuwen als het product te duur is ten opzichte van het voordeel?',antwoord:`Ja. Kosten zijn onderdeel van de passendheid. Is het verwachte voordeel kleiner dan de kosten, dan bespreekt u dat. Leg de kostenafweging vast. Dit speelt vaak bij oversluiten en bij kleine verzekeringen met hoge kosten.`,tags:['kosten','passend advies','zorgplicht'],bron:'Wft'},
 {id:'cpx-030',thema:'compliance',vraag:'Hoe leg ik het klantbelang centraal vast in mijn adviesproces?',antwoord:`Beschrijf in uw procesdocumentatie hoe u het klantbelang borgt. Denk aan vaste stappen voor klantprofiel, analyse, advies en nazorg. Toets steekproefsgewijs dossiers op deze stappen. Leg verbeterpunten vast en volg ze op.`,tags:['klantbelang','adviesproces','kwaliteitsborging'],bron:'AFM'},
 {id:'cpx-031',thema:'compliance',vraag:'Wat is een veelgemaakte fout in het klantprofiel?',antwoord:`Een veelgemaakte fout is een profiel dat alleen uit aangevinkte vakjes bestaat. Een andere fout is een profiel dat niet terugkomt in het advies. Ook ontbreekt vaak de toekomstige situatie, zoals pensioen of gezinsuitbreiding. Zorg voor een aantoonbare koppeling tussen profiel en advies.`,tags:['klantprofiel','fouten','dossierkwaliteit'],bron:'AFM'},
 {id:'cpx-032',thema:'compliance',vraag:'Moet ik de toekomstige inkomenssituatie meenemen?',antwoord:`Ja, voor zover die redelijkerwijs te voorzien is. Denk aan pensionering, afloop van een tijdelijk contract of minder gaan werken. Bespreek de gevolgen voor de lasten. Leg de besproken scenarios vast.`,tags:['toekomstig inkomen','scenario','passend advies'],bron:'Wft'},
 {id:'cpx-033',thema:'compliance',vraag:'Hoe adviseer ik bij een echtscheiding?',antwoord:`Breng de situatie van beide partijen apart in kaart. Let op belangenconflicten als u beide partners adviseert. Bespreek wie de woning overneemt, het ontslag uit hoofdelijke aansprakelijkheid en de verdeling van verzekeringen. Leg vast wie uw opdrachtgever is.`,tags:['echtscheiding','belangenconflict','hoofdelijkheid'],bron:'Wft'},
 {id:'cpx-034',thema:'compliance',vraag:'Mag ik beide ex-partners adviseren?',antwoord:`Dat kan, maar alleen als u beide belangen zorgvuldig kunt behartigen. Informeer beide partijen over het mogelijke belangenconflict. Bij tegengestelde belangen kan het beter zijn een van beiden door te verwijzen. Leg de afspraken en de toestemming vast.`,tags:['echtscheiding','belangenconflict','ex-partners'],bron:'Wft'},
 {id:'cpx-035',thema:'compliance',vraag:'Hoe adviseer ik een zzp-er passend over inkomensrisicos?',antwoord:`Breng het inkomen, de vaste lasten, de buffer en bestaande voorzieningen in kaart. Bespreek de gevolgen van arbeidsongeschiktheid en de verschillende oplossingen. Een klant die geen verzekering wil, maakt een bewuste keuze. Leg het besproken risico en de keuze vast.`,tags:['zzp','inkomensrisico','arbeidsongeschiktheid'],bron:'Wft'},
 {id:'cpx-036',thema:'compliance',vraag:'Hoe leg ik vast dat de klant het renterisico na de rentevaste periode begrijpt?',antwoord:`Laat in een scenario zien wat de maandlast wordt bij een hogere rente na afloop van de rentevaste periode. Gebruik daarvoor een rekentool met actuele uitgangspunten. Vraag de klant of hij die last kan dragen en wat hij dan zou doen. Leg het scenario en de reactie van de klant vast.`,tags:['renterisico','scenario','vastlegging'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-037',thema:'compliance',vraag:'Moet ik werkloosheid bespreken bij een klant met vast contract?',antwoord:`Ja. Ook een vast contract sluit werkloosheid niet uit. Laat zien wat een WW-situatie betekent voor de woonlasten. Bespreek de buffer en mogelijke voorzieningen. Leg vast dat het risico is besproken.`,tags:['werkloosheid','risicoanalyse','hypotheek'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-038',thema:'compliance',vraag:'Hoe concreet moet de risicoanalyse zijn?',antwoord:`De risicoanalyse moet gaan over de situatie van deze klant. Toon in bedragen wat er gebeurt bij arbeidsongeschiktheid, werkloosheid, overlijden en pensioen. Algemene teksten zonder cijfers zijn onvoldoende. Koppel elk risico aan een besproken oplossing of een bewuste keuze.`,tags:['risicoanalyse','concreet','dossier'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-039',thema:'compliance',vraag:'Wat is het verschil tussen adviseren en informeren over risicos?',antwoord:`Informeren is uitleggen welke risicos er zijn. Adviseren is aangeven welke oplossing u voor deze klant aanbeveelt. De klant moet het risico begrijpen en een keuze kunnen maken. Leg zowel de informatie als uw aanbeveling vast.`,tags:['risicos','informeren','adviseren'],bron:'Wft'},
 {id:'cpx-040',thema:'compliance',vraag:'Mag ik bij een hypotheekadvies verzekeringen weglaten op verzoek van de klant?',antwoord:`Ja, de klant mag een risico zelf dragen. U moet het risico wel bespreken en de gevolgen laten zien. Vraag de klant waarom hij geen voorziening wil. Leg het gesprek en de keuze vast.`,tags:['risico zelf dragen','hypotheek','vastlegging'],bron:'Wft'},
 {id:'cpx-041',thema:'compliance',vraag:'Hoe weeg ik een klantwens af die slecht is voor de klant?',antwoord:`Leg uit waarom de wens volgens u niet passend is. Toon de gevolgen in een concreet voorbeeld. Houdt de klant vast aan de wens, dan beslist u of u dit afwijkend wilt uitvoeren of de dienstverlening weigert. Leg het gesprek uitgebreid vast.`,tags:['klantwens','afwijkend','zorgplicht'],bron:'Wft'},
 {id:'cpx-042',thema:'compliance',vraag:'Mag ik een adviestraject weigeren?',antwoord:`Ja. U bent niet verplicht een klant aan te nemen of een opdracht uit te voeren. Weiger bijvoorbeeld als u geen passend advies kunt geven of als er integriteitsrisicos zijn. Communiceer de weigering zorgvuldig. Leg de reden intern vast.`,tags:['weigeren','acceptatie','integriteit'],bron:'Wft'},
 {id:'cpx-043',thema:'compliance',vraag:'Hoe adviseer ik bij een klant met schulden in het BKR?',antwoord:`Breng de schulden en de betalingshistorie volledig in kaart. Volg de acceptatieregels van de geldverstrekker. Bespreek of financieren verantwoord is gezien de totale lasten. Leg uw beoordeling vast, ook als u adviseert om niet te financieren.`,tags:['BKR','schulden','kredietwaardigheid'],bron:'Wft'},
 {id:'cpx-044',thema:'compliance',vraag:'Wat is een kredietwaardigheidstoets?',antwoord:`Een kredietverstrekker moet vóór het verstrekken van krediet beoordelen of de klant het krediet kan dragen. Dit voorkomt overkreditering. De adviseur levert daarvoor juiste en volledige gegevens aan. Een adviseur die bewust onjuiste gegevens aanlevert, handelt in strijd met de zorgplicht.`,tags:['kredietwaardigheid','overkreditering','krediet'],bron:'Wft'},
 {id:'cpx-045',thema:'compliance',vraag:'Hoe adviseer ik passend over consumptief krediet naast een hypotheek?',antwoord:`Kijk naar het totaal van de lasten en niet alleen naar het nieuwe krediet. Toets of de klant beide verplichtingen kan dragen. Bespreek het risico van doorlopend krediet en de kosten. Leg uw afweging vast.`,tags:['consumptief krediet','totale lasten','passend advies'],bron:'Wft'},
 {id:'cpx-046',thema:'compliance',vraag:'Moet ik de doelstelling achter een krediet vastleggen?',antwoord:`Ja. Het doel bepaalt welke vorm van krediet passend is. Een auto vraagt iets anders dan een tijdelijk tekort. Vraag door als het doel vaag is. Leg het doel en de koppeling met het advies vast.`,tags:['krediet','doel','vastlegging'],bron:'Wft'},
 {id:'cpx-047',thema:'compliance',vraag:'Wat is de rol van de Gedragscode Hypothecaire Financieringen?',antwoord:`De Gedragscode Hypothecaire Financieringen bevat afspraken van geldverstrekkers over verantwoord lenen. Denk aan zekerheid, tijdige informatie en omgang met klanten. Geldverstrekkers volgen de code en vertalen die in hun acceptatiebeleid. Raadpleeg de actuele versie bij de NVB.`,tags:['gedragscode','hypotheek','geldverstrekker'],bron:'NVB'},
 {id:'cpx-048',thema:'compliance',vraag:'Hoe adviseer ik passend bij een maximale hypotheek?',antwoord:`Een maximale hypotheek volgens de leennormen is niet automatisch passend. Bespreek de vrije bestedingsruimte en toekomstige wijzigingen. Toon wat er gebeurt bij lagere inkomsten of hogere lasten. Leg vast waarom het bedrag voor deze klant verantwoord is.`,tags:['maximale hypotheek','betaalbaarheid','passend advies'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-049',thema:'compliance',vraag:'Wat is het verschil tussen leencapaciteit en betaalbaarheid?',antwoord:`Leencapaciteit is wat volgens de normen maximaal kan. Betaalbaarheid is wat de klant in zijn eigen situatie kan dragen. Een klant met hoge vaste lasten of plannen kan minder dragen dan de norm toestaat. Bespreek beide en leg de afweging vast.`,tags:['leencapaciteit','betaalbaarheid','Nibud'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-050',thema:'compliance',vraag:'Moet ik een uitgavenpatroon van de klant opvragen?',antwoord:`Voor een goede betaalbaarheidsanalyse is inzicht in vaste lasten en uitgaven nodig. Een budgetoverzicht helpt om de vrije ruimte te bepalen. Bespreek bijzondere uitgaven zoals kinderopvang of auto. Leg het overzicht of de inschatting vast.`,tags:['uitgaven','budget','betaalbaarheid'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-051',thema:'compliance',vraag:'Wat moet minimaal in een klantdossier zitten?',antwoord:`Een klantdossier bevat in ieder geval:
- het klantprofiel met onderbouwende stukken
- de inventarisatie en analyse
- het advies met motivering
- de informatie die de klant heeft ontvangen
- afspraken over dienstverlening en kosten
Zo kan een derde het advies achteraf volgen.`,tags:['dossier','minimale inhoud','vastlegging'],bron:'Wft'},
 {id:'cpx-052',thema:'compliance',vraag:'Wanneer is een dossier navolgbaar?',antwoord:`Een dossier is navolgbaar als een buitenstaander kan zien welke informatie u had, welke afwegingen u maakte en waarom u tot dit advies kwam. Losse stukken zonder samenhang zijn onvoldoende. Een korte motivering per adviesonderdeel helpt veel. Test dit door een collega een dossier te laten lezen.`,tags:['dossier','navolgbaarheid','kwaliteit'],bron:'AFM'},
 {id:'cpx-053',thema:'compliance',vraag:'Mag ik gespreksaantekeningen achteraf aanvullen?',antwoord:`U mag aantekeningen aanvullen, maar maak zichtbaar wanneer en door wie dat is gebeurd. Wijzig nooit stukken zonder datum, zeker niet na een klacht. Achteraf aangepaste stukken tasten de geloofwaardigheid van het dossier aan. Gebruik bij voorkeur een systeem met versiebeheer.`,tags:['gespreksverslag','aanvullen','versiebeheer'],bron:'Wft'},
 {id:'cpx-054',thema:'compliance',vraag:'Moet ik een gespreksverslag naar de klant sturen?',antwoord:`Het is geen algemene wettelijke eis, maar wel sterk aan te raden. De klant kan dan reageren als iets niet klopt. Bij een latere klacht staat u sterker. Leg vast wanneer het verslag is verstuurd.`,tags:['gespreksverslag','klant','bewijs'],bron:'Wft'},
 {id:'cpx-055',thema:'compliance',vraag:'Mag ik adviesgesprekken opnemen?',antwoord:`Dat kan, mits u de AVG naleeft. Informeer de klant vooraf over het opnemen, het doel en de bewaartermijn. Bewaar opnames beveiligd en niet langer dan nodig. Een opname vervangt geen schriftelijke vastlegging van het advies.`,tags:['opname','gesprek','AVG'],bron:'AVG'},
 {id:'cpx-056',thema:'compliance',vraag:'Hoe leg ik een advies vast dat in meerdere gesprekken tot stand kwam?',antwoord:`Maak per gesprek een kort verslag met datum en besproken onderwerpen. Vat in het adviesrapport de eindconclusie samen. Laat zien hoe gewijzigde wensen of gegevens het advies hebben beïnvloed. Zo blijft de lijn in het dossier zichtbaar.`,tags:['meerdere gesprekken','verslag','adviesrapport'],bron:'Wft'},
 {id:'cpx-057',thema:'compliance',vraag:'Wat is een veelgemaakte fout in adviesrapporten?',antwoord:`Een veelgemaakte fout is een rapport vol standaardteksten zonder koppeling aan de klant. Ook ontbreken vaak de risicobespreking en de motivering van productkeuzes. Een ander probleem is een rapport dat niet aansluit op de feitelijk afgesloten producten. Controleer het rapport tegen de definitieve offerte.`,tags:['adviesrapport','standaardteksten','fouten'],bron:'AFM'},
 {id:'cpx-058',thema:'compliance',vraag:'Moet het adviesrapport overeenkomen met het afgesloten product?',antwoord:`Ja. Wijkt het afgesloten product af van het advies, dan moet u dat verklaren en vastleggen. Denk aan een andere rentevaste periode of een ander bedrag. Pas zo nodig het advies aan of leg vast waarom de klant afwijkt. Een ongemotiveerd verschil is een risico bij een klacht.`,tags:['adviesrapport','offerte','afwijking'],bron:'Wft'},
 {id:'cpx-059',thema:'compliance',vraag:'Hoe leg ik een afwijkend advies vast?',antwoord:`Leg vast wat u adviseerde, waarin de klant afwijkt en waarom. Beschrijf de risicos en gevolgen die u hebt besproken, bij voorkeur in bedragen. Laat de klant bevestigen dat hij de risicos begrijpt. Een standaard afstandsverklaring zonder inhoud is onvoldoende.`,tags:['afwijkend advies','vastlegging','risicos'],bron:'Wft'},
 {id:'cpx-060',thema:'compliance',vraag:'Wanneer mag ik een afwijkende klantwens niet uitvoeren?',antwoord:`Als uitvoeren in strijd is met wet of leennormen kunt u niet meewerken. Ook als de gevolgen voor de klant ernstig en onomkeerbaar zijn, kunt u besluiten niet mee te werken. De zorgplicht weegt dan zwaarder dan de wens. Leg uw besluit en de reden vast.`,tags:['afwijkend advies','weigeren','zorgplicht'],bron:'Wft'},
 {id:'cpx-061',thema:'compliance',vraag:'Wat doe ik als de gezinssituatie tijdens het adviestraject verandert?',antwoord:`Actualiseer het klantprofiel en beoordeel of het advies nog passend is. Denk aan samenwonen, een scheiding of een kind op komst. Pas zo nodig het advies en de risicoanalyse aan. Leg de wijziging en de gevolgen vast.`,tags:['klantprofiel','wijziging','actualiseren'],bron:'Wft'},
 {id:'cpx-062',thema:'compliance',vraag:'Kan ik achteraf een adviestraject omzetten naar execution only?',antwoord:`Dat is riskant. Als u al persoonlijke aanbevelingen hebt gedaan, is er sprake van advies. Een latere omzetting neemt die adviesverantwoordelijkheid niet weg. Maak vooraf duidelijke afspraken over de vorm van dienstverlening.`,tags:['execution only','omzetten','adviesverantwoordelijkheid'],bron:'Wft'},
 {id:'cpx-063',thema:'compliance',vraag:'Welke informatie geef ik bij execution only?',antwoord:`Ook bij execution only geeft u de klant informatie over het product, de kosten en de risicos. Maak duidelijk dat u niet toetst of het product passend is. Bij bepaalde producten kan een kennis- en ervaringstoets nodig zijn. Leg de gegeven informatie en de keuze van de klant vast.`,tags:['execution only','informatie','risicos'],bron:'Wft'},
 {id:'cpx-064',thema:'compliance',vraag:'Welke informatie moet ik vóór de dienstverlening geven?',antwoord:`De klant moet vooraf weten wie u bent, welke diensten u verleent, hoe u wordt beloond en wat de kosten zijn. Ook informeert u over de klachtenprocedure en de aansluiting bij Kifid. Geef aan of u met een beperkt aantal aanbieders werkt. Leg vast wanneer de klant de informatie ontving.`,tags:['informatieplicht','precontractueel','kosten'],bron:'Wft'},
 {id:'cpx-065',thema:'compliance',vraag:'Wanneer mag ik mij onafhankelijk noemen?',antwoord:`De term onafhankelijk is beschermd. U moet uw advies baseren op een voldoende aantal in de markt verkrijgbare producten van verschillende aanbieders. Ook mag u geen provisie of andere beloning van aanbieders ontvangen voor die dienstverlening. Controleer de actuele voorwaarden in de Wft.`,tags:['onafhankelijk','beloning','aanbieders'],bron:'Wft'},
 {id:'cpx-066',thema:'compliance',vraag:'Hoe licht ik een beperkte selectie van aanbieders toe?',antwoord:`Vertel de klant met welke aanbieders u werkt en waarom. Leg uit dat u alleen uit die selectie adviseert. Vermeld dit in uw informatie vooraf en in het adviesrapport. Zo kan de klant de reikwijdte van het advies beoordelen.`,tags:['aanbieders','selectie','informatieplicht'],bron:'Wft'},
 {id:'cpx-067',thema:'compliance',vraag:'Hoe presenteer ik kosten begrijpelijk?',antwoord:`Noem een totaalbedrag of een duidelijke tariefstructuur. Maak onderscheid tussen advies, bemiddeling en eventuele nazorg. Vermijd alleen een uurtarief zonder inschatting van het aantal uren. Bevestig de kostenafspraak schriftelijk.`,tags:['kosten','transparantie','tarief'],bron:'Wft'},
 {id:'cpx-068',thema:'compliance',vraag:'Mag ik een vast tarief rekenen ongeacht de uitkomst?',antwoord:`Ja, een vast tarief is toegestaan als het vooraf duidelijk is afgesproken. Leg vast wat de klant krijgt voor dat tarief. Maak afspraken over wat er gebeurt als het traject wordt afgebroken. Zorg dat het tarief geen ongewenste prikkel geeft.`,tags:['vast tarief','afspraken','beloning'],bron:'Wft'},
 {id:'cpx-069',thema:'compliance',vraag:'Hoe reken ik kosten bij een afgebroken traject?',antwoord:`Spreek vooraf af welk deel van de kosten verschuldigd is per fase. Factureer achteraf alleen wat is afgesproken. Leg vast in welke fase het traject stopte. Onduidelijke afspraken leiden vaak tot klachten.`,tags:['afgebroken traject','kosten','afspraken'],bron:'Wft'},
 {id:'cpx-070',thema:'compliance',vraag:'Mag ik een abonnement voor nazorg aanbieden?',antwoord:`Ja. De vergoeding moet passen bij de dienstverlening die u feitelijk levert. Beschrijf wat het abonnement omvat en hoe vaak u contact opneemt. Lever die dienst ook aantoonbaar. Een abonnement zonder feitelijke dienstverlening is een bekend aandachtspunt van de AFM.`,tags:['abonnement','nazorg','servicevergoeding'],bron:'AFM'},
 {id:'cpx-071',thema:'compliance',vraag:'Hoe toon ik aan dat ik de beloofde nazorg heb geleverd?',antwoord:`Leg contactmomenten, periodieke controles en gegeven adviezen vast. Bewaar uitnodigingen en verslagen. Houd per klant bij welke diensten onder het abonnement zijn uitgevoerd. Zo kunt u bij vragen van klant of toezichthouder de waarde onderbouwen.`,tags:['nazorg','bewijs','abonnement'],bron:'AFM'},
 {id:'cpx-072',thema:'compliance',vraag:'Mag ik provisie ontvangen voor schadeverzekeringen?',antwoord:`Voor veel schadeverzekeringen is provisie nog toegestaan. Wel moet u de klant informeren over de aard van de beloning. De beloning mag het klantbelang niet schaden. Controleer per product of het provisieverbod geldt.`,tags:['provisie','schadeverzekering','transparantie'],bron:'Wft'},
 {id:'cpx-073',thema:'compliance',vraag:'Wat is een veelgemaakte fout rond het provisieverbod?',antwoord:`Een fout is het ontvangen van verkapte beloningen, zoals vergoedingen voor diensten die niet echt worden geleverd. Ook bonussen of reizen van aanbieders kunnen in strijd zijn met de regels. Kijk naar de inhoud van de vergoeding, niet naar de naam. Leg ontvangen vergoedingen en de toetsing vast.`,tags:['provisieverbod','verkapte beloning','fouten'],bron:'Wft'},
 {id:'cpx-074',thema:'compliance',vraag:'Mag ik een vergoeding van een aanbieder ontvangen voor het beheer van een portefeuille?',antwoord:`Alleen als de vergoeding past binnen de regels voor uw productcategorie. Bij producten onder het provisieverbod is een beloning van de aanbieder in verband met de dienstverlening aan de klant niet toegestaan. Een vergoeding voor werkelijk verrichte uitbestede werkzaamheden kan anders liggen. Laat dit juridisch toetsen en leg de onderbouwing vast.`,tags:['provisieverbod','uitbesteding','vergoeding'],bron:'Wft'},
 {id:'cpx-075',thema:'compliance',vraag:'Welke regels gelden voor de beloning van mijn medewerkers?',antwoord:`Het beloningsbeleid mag geen prikkels bevatten die het klantbelang schaden. Variabele beloning gekoppeld aan productie is daarom een risico. Voor financiële ondernemingen geldt bovendien een wettelijk plafond voor variabele beloning. Leg het beleid vast en evalueer het periodiek.`,tags:['beloningsbeleid','medewerkers','variabele beloning'],bron:'Wft'},
 {id:'cpx-076',thema:'compliance',vraag:'Mag ik medewerkers belonen op basis van klanttevredenheid?',antwoord:`Dat is beter dan beloning op productie, maar ook hier gelden de regels voor variabele beloning. Zorg dat de criteria het klantbelang echt bevorderen. Meet bij voorkeur ook kwaliteit, zoals dossiertoetsing. Leg het beloningsbeleid schriftelijk vast.`,tags:['beloning','klanttevredenheid','kwaliteit'],bron:'Wft'},
 {id:'cpx-077',thema:'compliance',vraag:'Mag een aanbieder mij een cadeau geven?',antwoord:`Kleine attenties kunnen, maar zijn niet onbeperkt toegestaan. Bij producten onder het provisieverbod gelden strenge regels. Leg in een integriteitsbeleid vast wat acceptabel is. Registreer ontvangen geschenken en uitnodigingen.`,tags:['geschenken','integriteit','aanbieders'],bron:'Wft'},
 {id:'cpx-078',thema:'compliance',vraag:'Hoe ga ik om met een inducement bij beleggingsdiensten?',antwoord:`Bij beleggingsdiensten gelden aparte en strenge regels voor provisies en andere voordelen van derden. Ontvangen is alleen in beperkte situaties toegestaan, met transparantie richting de klant. Voor veel adviseurs is dit buiten de vergunning. Raadpleeg de regels en uw vergunning voordat u iets accepteert.`,tags:['inducement','beleggen','provisie'],bron:'Wft'},
 {id:'cpx-079',thema:'compliance',vraag:'Moet ik de kosten van de geldverstrekker apart toelichten?',antwoord:`Ja. De klant moet weten welke kosten bij u liggen en welke bij de geldverstrekker of verzekeraar. Denk aan afsluitkosten, taxatie en notaris. Een totaaloverzicht van alle kosten helpt de klant. Leg vast dat de kosten zijn toegelicht.`,tags:['kosten','geldverstrekker','overzicht'],bron:'Wft'},
 {id:'cpx-080',thema:'compliance',vraag:'Wat is het ESIS bij een hypotheek?',antwoord:`Het ESIS is het Europees gestandaardiseerd informatieblad over een hypothecair krediet. De geldverstrekker verstrekt het bij een aanbod. Het bevat onder meer kosten, rente en risicos in een vaste opbouw. Bespreek het ESIS met de klant en leg vast dat hij het heeft ontvangen.`,tags:['ESIS','hypotheek','informatie'],bron:'Wft'},
 {id:'cpx-081',thema:'compliance',vraag:'Mag een klant zijn dossier meenemen naar een andere adviseur?',antwoord:`De klant kan een kopie vragen van zijn persoonsgegevens en de stukken die hij heeft aangeleverd. U bewaart zelf het dossier voor uw bewaarplichten en als bewijs. Draag gegevens alleen over aan de nieuwe adviseur met een duidelijke opdracht van de klant. Leg het verzoek en de overdracht vast.`,tags:['dossieroverdracht','inzage','AVG'],bron:'AVG'},
 {id:'cpx-082',thema:'compliance',vraag:'Mag ik de klant onder tijdsdruk laten tekenen?',antwoord:`Nee, voorkom dit. De klant moet voldoende tijd hebben om de stukken te lezen en vragen te stellen. Tijdsdruk door een ontbindende voorwaarde of een renteaanbod is een bekend risico. Leg vast hoe u de klant toch voldoende tijd gaf.`,tags:['tijdsdruk','ondertekening','zorgplicht'],bron:'Wft'},
 {id:'cpx-083',thema:'compliance',vraag:'Mag ik een advies baseren op een verwachte erfenis of schenking?',antwoord:`Wees terughoudend. Een verwachte erfenis is onzeker in hoogte en moment. Baseer het advies op wat vaststaat en bespreek het verwachte vermogen hooguit als scenario. Leg vast welke aannames u wel en niet hebt gebruikt.`,tags:['erfenis','aannames','passend advies'],bron:'Wft'},
 {id:'cpx-084',thema:'compliance',vraag:'Mag ik een advies van een ander kantoor alleen uitvoeren?',antwoord:`Dat kan als execution only of als bemiddeling zonder eigen advies, mits dit vooraf duidelijk is afgesproken. Toets wel of u signalen ziet dat het product duidelijk niet past. Blijkt uit het contact dat u toch adviseert, dan gelden de adviesregels. Leg de afspraak over de dienstverlening vast.`,tags:['uitvoeren','execution only','afspraken'],bron:'Wft'},
 {id:'cpx-085',thema:'compliance',vraag:'Is een digitale handtekening geldig voor een adviesrapport?',antwoord:`Een elektronische handtekening kan rechtsgeldig zijn. De bewijskracht hangt af van de betrouwbaarheid van de methode. Kies een methode die de identiteit van de ondertekenaar en de integriteit van het document borgt. Controleer ook de eisen van de geldverstrekker of verzekeraar.`,tags:['digitale handtekening','ondertekening','bewijs'],bron:'Burgerlijk Wetboek'},
 {id:'cpx-086',thema:'compliance',vraag:'Hoe ga ik om met een klant die het adviesrapport niet wil tekenen?',antwoord:`Een handtekening is geen wettelijke voorwaarde voor een geldig advies. Vraag naar de reden en bespreek eventuele bezwaren. Leg vast dat het rapport is verstrekt en besproken. Bevestig het advies per e-mail als bewijs van verzending.`,tags:['ondertekening','adviesrapport','weigering'],bron:'Wft'},
 {id:'cpx-087',thema:'compliance',vraag:'Wat is het risico van standaard afstandsverklaringen?',antwoord:`Een afstandsverklaring beschermt u weinig als de inhoud niet blijkt uit het dossier. De rechter en Kifid kijken naar wat feitelijk is besproken. Een verklaring zonder concrete risicos en gevolgen wordt vaak terzijde geschoven. Beschrijf de situatie van deze klant concreet.`,tags:['afstandsverklaring','Kifid','bewijs'],bron:'Kifid'},
 {id:'cpx-088',thema:'compliance',vraag:'Hoe documenteer ik een besproken scenario met rekenvoorbeeld?',antwoord:`Beschrijf het scenario, de aannames en de uitkomst in bedragen. Bijvoorbeeld: bij een inkomensdaling van een derde stijgt de woonquote zodanig dat het budget negatief wordt. Vermeld welke oplossingen zijn besproken. Gebruik actuele bedragen uit uw rekentool en bewaar de berekening.`,tags:['scenario','rekenvoorbeeld','vastlegging'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-089',thema:'compliance',vraag:'Wie moet het adviesrapport ondertekenen namens de onderneming?',antwoord:`Het rapport moet herleidbaar zijn tot een vakbekwame adviseur. Vermeld de naam van de adviseur die het advies gaf. Bij advies onder begeleiding vermeldt u ook de begeleidende vakbekwame adviseur. Zo is duidelijk wie verantwoordelijk is.`,tags:['adviesrapport','ondertekening','vakbekwaamheid'],bron:'Wft'},
 {id:'cpx-090',thema:'compliance',vraag:'Hoe bewaar ik dossiers bij overname van een klantenportefeuille?',antwoord:`Neem bij de overname afspraken op over de dossiers en hun volledigheid. Controleer steekproefsgewijs de kwaliteit vooraf. Informeer klanten over de overdracht en hun gegevens. Bewaar de dossiers zo dat u eerder gegeven adviezen kunt reconstrueren.`,tags:['portefeuilleoverdracht','dossiers','AVG'],bron:'Wft'},
 {id:'cpx-091',thema:'compliance',vraag:'Ben ik aansprakelijk voor adviezen van mijn voorganger?',antwoord:`Dat hangt af van de afspraken bij de overname. Bij overname van een onderneming kan de aansprakelijkheid meegaan. Bij overdracht van alleen klanten ligt dat vaak anders. Laat dit juridisch toetsen en leg het vast in de overnameovereenkomst.`,tags:['aansprakelijkheid','overname','voorganger'],bron:'Burgerlijk Wetboek'},
 {id:'cpx-092',thema:'compliance',vraag:'Moet ik bij een portefeuilleoverdracht de klanten toestemming vragen?',antwoord:`Klanten moeten in ieder geval goed worden geïnformeerd. Of toestemming nodig is, hangt af van de constructie en de AVG-grondslag. Bied klanten de mogelijkheid om bezwaar te maken of over te stappen. Leg de communicatie vast.`,tags:['portefeuilleoverdracht','klanten','toestemming'],bron:'AVG'},
 {id:'cpx-093',thema:'compliance',vraag:'Wat doe ik als ik een fout ontdek in een oud advies?',antwoord:`Analyseer de fout en de gevolgen voor de klant. Informeer de klant en zoek samen een oplossing. Meld het zo nodig bij uw beroepsaansprakelijkheidsverzekeraar. Leg de analyse en de stappen vast.`,tags:['fout','herstel','aansprakelijkheid'],bron:'Wft'},
 {id:'cpx-094',thema:'compliance',vraag:'Moet ik een mogelijke claim melden bij mijn verzekeraar?',antwoord:`De polisvoorwaarden schrijven meestal voor dat u omstandigheden die tot een claim kunnen leiden tijdig meldt. Te laat melden kan de dekking in gevaar brengen. Controleer de voorwaarden van uw beroepsaansprakelijkheidsverzekering. Leg de melding en de reactie vast.`,tags:['claim','melding','BAV'],bron:''},
 {id:'cpx-095',thema:'compliance',vraag:'Hoe leg ik een telefoongesprek over een wijziging vast?',antwoord:`Noteer datum, tijd, gesprekspartner en de besproken wijziging. Noteer ook wat u hebt geadviseerd en wat de klant besliste. Bevestig belangrijke wijzigingen per e-mail. Zo voorkomt u discussie achteraf.`,tags:['telefoon','wijziging','vastlegging'],bron:'Wft'},
 {id:'cpx-096',thema:'compliance',vraag:'Wat is het verschil tussen een adviesdossier en een bedrijfsdossier?',antwoord:`Het adviesdossier gaat over een klant en het advies aan die klant. Het bedrijfsdossier gaat over uw onderneming, zoals vergunning, beleid, vakbekwaamheid en integriteit. Beide moet u op orde hebben. De AFM kan naar beide vragen.`,tags:['adviesdossier','bedrijfsdossier','AFM'],bron:'AFM'},
 {id:'cpx-097',thema:'compliance',vraag:'Wat hoort in het bedrijfsdossier?',antwoord:`Denk aan:
- vergunning en AFM-registratie
- beleid voor integriteit, beloning en klachten
- vakbekwaamheid van medewerkers
- SIRA en Wwft-procedures
- verwerkingsregister en AVG-documenten
Houd het dossier actueel.`,tags:['bedrijfsdossier','beleid','compliance'],bron:'AFM'},
 {id:'cpx-098',thema:'compliance',vraag:'Hoe vaak moet ik mijn compliancebeleid herzien?',antwoord:`De wet geeft geen vaste frequentie voor alle onderdelen. Een jaarlijkse evaluatie is een goed uitgangspunt. Herzie ook bij nieuwe regels, nieuwe diensten of incidenten. Leg de evaluatie en de wijzigingen vast.`,tags:['compliancebeleid','evaluatie','actualiseren'],bron:'AFM'},
 {id:'cpx-099',thema:'compliance',vraag:'Mag ik compliancetaken uitbesteden?',antwoord:`Ja, u kunt werkzaamheden uitbesteden aan een externe partij. De verantwoordelijkheid blijft bij uw onderneming. Leg de afspraken vast in een uitbestedingsovereenkomst. Controleer periodiek of de partij goed presteert.`,tags:['uitbesteding','compliance','verantwoordelijkheid'],bron:'Wft'},
 {id:'cpx-100',thema:'compliance',vraag:'Wat doe ik met een kwaliteitstoets die gebreken in dossiers laat zien?',antwoord:`Analyseer of het gaat om losse fouten of een structureel probleem. Herstel de dossiers waar de klant nadeel kan hebben. Pas het proces of de opleiding aan. Leg de bevindingen en maatregelen vast.`,tags:['dossiertoetsing','kwaliteit','verbetering'],bron:'AFM'},
 {id:'cpx-101',thema:'compliance',vraag:'Wat gebeurt er als een adviseur zijn PE-verplichting niet haalt?',antwoord:`De adviseur is dan niet meer vakbekwaam voor de betreffende productcategorie. Hij mag op dat terrein niet zelfstandig adviseren. De onderneming moet dit signaleren en de werkzaamheden aanpassen. Leg de opvolging en het herstel vast.`,tags:['PE','vakbekwaamheid','gevolgen'],bron:'Wft'},
 {id:'cpx-102',thema:'compliance',vraag:'Hoe houd ik als onderneming de vakbekwaamheid van medewerkers bij?',antwoord:`Houd per medewerker een overzicht bij van diplomas, PE-resultaten en geldigheid. Koppel dit aan de productcategorieën waarin de medewerker adviseert. Plan tijdig herinneringen voor afloopdata. De AFM kan dit overzicht opvragen.`,tags:['vakbekwaamheid','registratie','medewerkers'],bron:'Wft'},
 {id:'cpx-103',thema:'compliance',vraag:'Wie stelt de eindtermen voor Wft-examens vast?',antwoord:`Het College Deskundigheid Financiële Dienstverlening stelt de eindtermen en toetstermen vast. Examens worden afgenomen door erkende exameninstituten. De eindtermen worden periodiek aangepast aan nieuwe regels en ontwikkelingen. Raadpleeg de actuele eindtermen bij het CDFD.`,tags:['CDFD','eindtermen','examens'],bron:'CDFD'},
 {id:'cpx-104',thema:'compliance',vraag:'Mag een medewerker zonder diploma klantgegevens inventariseren?',antwoord:`Ondersteunende werkzaamheden zonder advies of bemiddeling vallen niet altijd onder de diplomaplicht. Zodra de medewerker de klant adviseert of klantcontact heeft dat onder bemiddeling valt, gelden de vakbekwaamheidseisen. Beschrijf de taken per functie. Leg de taakafbakening vast.`,tags:['vakbekwaamheid','ondersteuning','taakafbakening'],bron:'Wft'},
 {id:'cpx-105',thema:'compliance',vraag:'Wat betekent werken onder begeleiding voor het dossier?',antwoord:`Uit het dossier moet blijken dat een vakbekwame adviseur het advies heeft gecontroleerd. Noteer wie begeleidde en wanneer de controle plaatsvond. Een handtekening zonder inhoudelijke toets is onvoldoende. Houd de begeleidingsperiode binnen de wettelijke grenzen.`,tags:['begeleiding','dossier','vakbekwaamheid'],bron:'Wft'},
 {id:'cpx-106',thema:'compliance',vraag:'Is vakbekwaamheid alleen een kwestie van diplomas?',antwoord:`Nee. Diplomas en PE vormen de wettelijke basis. Daarnaast moet een adviseur zijn kennis bijhouden over producten, regels en markt. Ook vaardigheden zoals gespreksvoering en ethiek tellen mee. Leg aanvullende opleidingen vast.`,tags:['vakbekwaamheid','kennis','vaardigheden'],bron:'Wft'},
 {id:'cpx-107',thema:'compliance',vraag:'Hoe ga ik om met een nieuw product waarvoor geen apart diploma bestaat?',antwoord:`Controleer onder welke productcategorie het product valt. Zorg dat de adviseur de kenmerken en risicos van het product echt kent. Volg zo nodig productopleiding van de aanbieder of een onafhankelijke partij. Leg de kennisopbouw vast.`,tags:['nieuw product','kennis','productcategorie'],bron:'Wft'},
 {id:'cpx-108',thema:'compliance',vraag:'Moet een dagelijks beleidsbepaler zelf vakbekwaam zijn?',antwoord:`De Wft stelt eisen aan geschiktheid van beleidsbepalers. Daarnaast moeten medewerkers die adviseren vakbekwaam zijn. Een beleidsbepaler die zelf adviseert, moet ook aan de vakbekwaamheidseisen voldoen. Controleer de actuele eisen bij de AFM.`,tags:['beleidsbepaler','geschiktheid','vakbekwaamheid'],bron:'Wft'},
 {id:'cpx-109',thema:'compliance',vraag:'Wat is het verschil tussen betrouwbaarheid en vakbekwaamheid?',antwoord:`Betrouwbaarheid gaat over integriteit, zoals antecedenten en gedrag. Vakbekwaamheid gaat over kennis en kunde. Beide eisen gelden voor wie adviseert of de onderneming leidt. Bij medewerkers kunt u betrouwbaarheid onder meer toetsen met een verklaring omtrent het gedrag.`,tags:['betrouwbaarheid','vakbekwaamheid','VOG'],bron:'Wft'},
 {id:'cpx-110',thema:'compliance',vraag:'Moet ik een VOG vragen van nieuwe medewerkers?',antwoord:`Een onderneming moet de betrouwbaarheid van medewerkers met klantcontact borgen. Een verklaring omtrent het gedrag is daarvoor een gangbaar middel. Leg in uw beleid vast voor welke functies u een VOG vraagt. Bewaar alleen wat nodig is in verband met de AVG.`,tags:['VOG','betrouwbaarheid','personeel'],bron:'Wft'},
 {id:'cpx-111',thema:'compliance',vraag:'Hoe vaak toets ik de betrouwbaarheid van zittende medewerkers?',antwoord:`De wet schrijft geen vaste frequentie voor. Neem in uw integriteitsbeleid op wanneer u opnieuw toetst. Bijvoorbeeld bij functiewijziging of signalen van integriteitsproblemen. Leg de toetsingen vast.`,tags:['betrouwbaarheid','periodieke toets','integriteit'],bron:'Wft'},
 {id:'cpx-112',thema:'compliance',vraag:'Welke ondernemingen zijn een Wwft-instelling in de advieswereld?',antwoord:`Niet elke financieel adviseur valt automatisch onder de Wwft. Dat hangt af van de diensten, zoals bemiddeling in levensverzekeringen. Controleer per dienst of u Wwft-plichtig bent. Ook als u niet plichtig bent, blijft integriteitsbeleid nodig.`,tags:['Wwft-instelling','reikwijdte','levensverzekering'],bron:'Wwft'},
 {id:'cpx-113',thema:'compliance',vraag:'Wat is een UBO?',antwoord:`Een UBO is de uiteindelijk belanghebbende van een onderneming of rechtspersoon. Het gaat om de natuurlijke persoon die eigenaar is of zeggenschap heeft. Bij zakelijke klanten moet u de UBO vaststellen en verifiëren. Leg de stappen en bronnen vast.`,tags:['UBO','cliëntenonderzoek','zakelijke klant'],bron:'Wwft'},
 {id:'cpx-114',thema:'compliance',vraag:'Mag ik voor het UBO-onderzoek alleen het UBO-register gebruiken?',antwoord:`Nee, het register is een hulpmiddel. U moet zelf redelijke maatregelen nemen om de UBO te verifiëren. Vraag onder meer een organogram of aandeelhoudersregister. Leg verschillen tussen register en eigen onderzoek vast.`,tags:['UBO-register','verificatie','cliëntenonderzoek'],bron:'Wwft'},
 {id:'cpx-115',thema:'compliance',vraag:'Wat is verscherpt cliëntenonderzoek?',antwoord:`Verscherpt onderzoek is nodig bij een hoger risico. Denk aan een PEP, een klant uit een land met een hoog risico of een ongebruikelijke structuur. U doet extra onderzoek naar herkomst van middelen en doel van de relatie. Leg de extra maatregelen en de goedkeuring vast.`,tags:['verscherpt onderzoek','risico','Wwft'],bron:'Wwft'},
 {id:'cpx-116',thema:'compliance',vraag:'Wanneer mag ik vereenvoudigd cliëntenonderzoek doen?',antwoord:`Bij een aantoonbaar laag risico mag u het onderzoek beperken. U moet die inschatting wel onderbouwen. Het onderzoek blijft nodig, alleen in lichtere vorm. Leg de risicoclassificatie vast.`,tags:['vereenvoudigd onderzoek','laag risico','Wwft'],bron:'Wwft'},
 {id:'cpx-117',thema:'compliance',vraag:'Hoe stel ik een risicoprofiel per klant op voor de Wwft?',antwoord:`Kijk naar klanttype, land, product, transactie en herkomst van middelen. Ken een risiconiveau toe, bijvoorbeeld laag, midden of hoog. Koppel aan elk niveau de mate van onderzoek. Leg de classificatie en de reden vast.`,tags:['risicoprofiel','cliëntenonderzoek','Wwft'],bron:'Wwft'},
 {id:'cpx-118',thema:'compliance',vraag:'Wat is het verschil tussen herkomst van middelen en herkomst van vermogen?',antwoord:`Herkomst van middelen gaat over het geld in deze transactie, zoals de eigen inbreng. Herkomst van vermogen gaat over hoe de klant zijn totale vermogen heeft opgebouwd. Bij hoger risico onderzoekt u beide. Leg vast welke stukken u hebt gezien.`,tags:['herkomst middelen','vermogen','Wwft'],bron:'Wwft'},
 {id:'cpx-119',thema:'compliance',vraag:'Welke stukken kan ik vragen bij een schenking voor de eigen inbreng?',antwoord:`Vraag een schenkingsakte of schenkingsovereenkomst en bankafschriften van de overboeking. Vraag ook wie de schenker is en waar diens geld vandaan komt als het risico dat vraagt. Controleer of het bedrag past bij de schenker. Leg de bevindingen vast.`,tags:['schenking','eigen inbreng','herkomst'],bron:'Wwft'},
 {id:'cpx-120',thema:'compliance',vraag:'Wat doe ik als het cliëntenonderzoek niet rond komt?',antwoord:`Kunt u het onderzoek niet afronden, dan mag u de zakelijke relatie niet aangaan of voortzetten. Beoordeel of er reden is voor een melding van een ongebruikelijke transactie. Leg de situatie en uw besluit vast. Informeer de klant niet over een eventuele melding.`,tags:['cliëntenonderzoek','afbreken','melding'],bron:'Wwft'},
 {id:'cpx-121',thema:'compliance',vraag:'Hoe ga ik om met een verwachte inkomensstijging in het advies?',antwoord:`Neem een verwachte stijging alleen mee als die voldoende zeker is en de geldverstrekker dat accepteert. Vraag onderbouwing, zoals een schriftelijke toezegging van de werkgever. Bespreek wat er gebeurt als de stijging uitblijft. Leg de onderbouwing en het besproken risico vast.`,tags:['inkomensstijging','onderbouwing','risico'],bron:'Wft'},
 {id:'cpx-122',thema:'compliance',vraag:'Wat zijn indicatoren voor een ongebruikelijke transactie?',antwoord:`Er zijn objectieve en subjectieve indicatoren. Objectief zijn vaste criteria uit de regelgeving. Subjectief is wanneer u reden hebt om te veronderstellen dat de transactie verband houdt met witwassen of terrorismefinanciering. Denk aan onverklaarbare contante stortingen of complexe constructies zonder logisch doel.`,tags:['indicatoren','ongebruikelijke transactie','witwassen'],bron:'Wwft'},
 {id:'cpx-123',thema:'compliance',vraag:'Ben ik beschermd na een melding te goeder trouw?',antwoord:`De Wwft geeft een vrijwaring voor een melding die te goeder trouw is gedaan. Dat beschermt tegen strafrechtelijke en civielrechtelijke aansprakelijkheid voor de melding zelf. Meld daarom zorgvuldig en feitelijk. Bewaar de onderbouwing.`,tags:['vrijwaring','melding','goede trouw'],bron:'Wwft'},
 {id:'cpx-124',thema:'compliance',vraag:'Hoe lang bewaar ik Wwft-gegevens?',antwoord:`Gegevens uit het cliëntenonderzoek bewaart u gedurende een wettelijke termijn na het einde van de zakelijke relatie. Die termijn is vijf jaar. Gegevens over een transactie bewaart u ook vijf jaar na uitvoering. Vernietig de gegevens daarna, tenzij een andere wet langer bewaren vraagt.`,tags:['bewaartermijn','Wwft','gegevens'],bron:'Wwft'},
 {id:'cpx-125',thema:'compliance',vraag:'Moet ik medewerkers trainen in de Wwft?',antwoord:`Ja. Medewerkers die betrokken zijn bij cliëntenonderzoek moeten ongebruikelijke transacties kunnen herkennen. Train ze periodiek en bij nieuwe regels. Leg deelname en inhoud van de training vast. De toezichthouder kan hiernaar vragen.`,tags:['training','Wwft','medewerkers'],bron:'Wwft'},
 {id:'cpx-126',thema:'compliance',vraag:'Wie houdt toezicht op de Wwft bij adviseurs?',antwoord:`Voor financiële ondernemingen onder Wft-toezicht is dat meestal de AFM of DNB. Welke toezichthouder bevoegd is, hangt af van het type onderneming. Bij adviseurs en bemiddelaars is dat in de regel de AFM. Controleer de actuele indeling.`,tags:['toezicht','Wwft','AFM'],bron:'Wwft'},
 {id:'cpx-127',thema:'compliance',vraag:'Moet ik bij een zakelijke klant ook de vertegenwoordiger identificeren?',antwoord:`Ja. U identificeert de persoon die namens de rechtspersoon optreedt en controleert de vertegenwoordigingsbevoegdheid. Gebruik daarvoor bijvoorbeeld het uittreksel uit het handelsregister. Leg de identificatie en bevoegdheid vast. Vergeet de UBO niet.`,tags:['vertegenwoordiger','zakelijke klant','identificatie'],bron:'Wwft'},
 {id:'cpx-128',thema:'compliance',vraag:'Hoe identificeer ik een klant die ik nooit fysiek zie?',antwoord:`Gebruik een betrouwbare methode voor identificatie op afstand. Combineer bijvoorbeeld een kopie van het identiteitsbewijs met een verificatie via een betaling van een eigen bankrekening of een erkende digitale identificatie. Het risico van identiteitsfraude is hoger. Leg de methode vast.`,tags:['identificatie','op afstand','fraude'],bron:'Wwft'},
 {id:'cpx-129',thema:'compliance',vraag:'Wat is het verschil tussen een PEP en een familielid van een PEP?',antwoord:`Een PEP is iemand met een prominente publieke functie. Familieleden en naaste geassocieerden vallen ook onder de verscherpte regels. In alle gevallen is verscherpt onderzoek nodig. Leg vast hoe u de PEP-status hebt vastgesteld.`,tags:['PEP','familie','verscherpt onderzoek'],bron:'Wwft'},
 {id:'cpx-130',thema:'compliance',vraag:'Blijft iemand een PEP na het neerleggen van de functie?',antwoord:`Na het einde van de functie blijft gedurende een bepaalde periode verhoogde aandacht nodig. Daarna beoordeelt u op basis van risico of verscherpt onderzoek nog nodig is. Controleer de actuele termijn in de regelgeving. Leg de beoordeling vast.`,tags:['PEP','einde functie','risico'],bron:'Wwft'},
 {id:'cpx-131',thema:'compliance',vraag:'Mag ik een klant weigeren vanwege witwasrisico?',antwoord:`Ja. Als het risico niet te beheersen is, mag u de relatie weigeren of beëindigen. Communiceer dit zakelijk, zonder te verwijzen naar een melding. Beoordeel ook of een melding nodig is. Leg uw besluit vast.`,tags:['weigeren','witwasrisico','Wwft'],bron:'Wwft'},
 {id:'cpx-132',thema:'compliance',vraag:'Wat is een sanctiescreening?',antwoord:`Bij een sanctiescreening controleert u of een klant of UBO op een sanctielijst staat. Dat volgt uit de Sanctiewet en Europese regels. Bij een treffer mag u geen diensten verlenen en meldt u dit. Leg de screening en het resultaat vast.`,tags:['sanctiescreening','Sanctiewet','UBO'],bron:'Sanctiewet'},
 {id:'cpx-133',thema:'compliance',vraag:'Wanneer doe ik opnieuw cliëntenonderzoek bij een bestaande klant?',antwoord:`Bij gewijzigde omstandigheden, nieuwe producten of signalen van risico. Ook periodiek, afhankelijk van het risicoprofiel. Een hoog risico vraagt vaker controle dan een laag risico. Leg de momenten en uitkomsten vast.`,tags:['periodiek onderzoek','bestaande klant','Wwft'],bron:'Wwft'},
 {id:'cpx-134',thema:'compliance',vraag:'Mag ik cliëntenonderzoek van een bank overnemen?',antwoord:`U kunt onder voorwaarden steunen op onderzoek van een andere Wwft-instelling. U blijft zelf verantwoordelijk voor de uitkomst. Zorg dat u de gegevens direct kunt krijgen. Leg de afspraken en de gegevens vast.`,tags:['cliëntenonderzoek','derden','verantwoordelijkheid'],bron:'Wwft'},
 {id:'cpx-135',thema:'compliance',vraag:'Hoe ga ik om met contant geld bij een vermogenstransactie?',antwoord:`Contant geld vergroot het witwasrisico. Vraag naar de herkomst en de reden voor contante betaling. Bij onvoldoende verklaring overweegt u een melding. Leg de verklaring en uw beoordeling vast.`,tags:['contant geld','witwasrisico','herkomst'],bron:'Wwft'},
 {id:'cpx-136',thema:'compliance',vraag:'Wat is een typisch witwassignaal bij een hypotheekaanvraag?',antwoord:`Voorbeelden zijn een onverklaarbare eigen inbreng, een lening van een onbekende derde of een koopprijs die sterk afwijkt van de marktwaarde. Ook snelle doorverkoop of onlogische constructies zijn signalen. Vraag door en verifieer. Leg de signalen en uw afweging vast.`,tags:['witwassen','hypotheek','signalen'],bron:'Wwft'},
 {id:'cpx-137',thema:'compliance',vraag:'Wat is het verschil tussen fraude en witwassen?',antwoord:`Fraude is misleiding om een voordeel te krijgen, zoals valse loonstroken. Witwassen is het verhullen van de criminele herkomst van geld. Beide kunnen in een dossier samenvallen. Fraude meldt u volgens uw incidentenprocedure, witwassignalen via de Wwft-route.`,tags:['fraude','witwassen','incidenten'],bron:'Wwft'},
 {id:'cpx-138',thema:'compliance',vraag:'Wat doe ik bij een vervalste werkgeversverklaring?',antwoord:`Werk niet mee aan de aanvraag. Bewaar de stukken en leg uw bevindingen vast. Beoordeel of een melding nodig is bij de geldverstrekker, de FIU of de politie. Raadpleeg uw interne incidentenprocedure.`,tags:['fraude','werkgeversverklaring','incident'],bron:'Wft'},
 {id:'cpx-139',thema:'compliance',vraag:'Wat is het Incidentenwaarschuwingssysteem?',antwoord:`Financiële instellingen kunnen gegevens van personen die betrokken zijn bij fraude vastleggen in een intern en extern verwijzingsregister. Dat gebeurt volgens het Protocol Incidentenwaarschuwingssysteem Financiële Instellingen. Adviseurs hebben hier geen directe toegang. Fraudesignalen kunt u wel melden aan de betrokken instelling.`,tags:['fraude','incidentenregister','PIFI'],bron:'PIFI'},
 {id:'cpx-140',thema:'compliance',vraag:'Moet ik een incidentenregister bijhouden?',antwoord:`Een onderneming moet incidenten die de integriteit raken signaleren en afhandelen. Een incidentenregister helpt om dit aantoonbaar te doen. Leg per incident de feiten, de maatregelen en de afloop vast. Gebruik het register ook om uw SIRA te actualiseren.`,tags:['incidentenregister','integriteit','SIRA'],bron:'Wft'},
 {id:'cpx-141',thema:'compliance',vraag:'Wat is een klokkenluidersregeling?',antwoord:`Een klokkenluidersregeling geeft medewerkers een veilige route om misstanden te melden. Voor werkgevers vanaf een bepaalde omvang is een interne meldprocedure verplicht. Ook kleine kantoren doen er goed aan een eenvoudige route te hebben. Leg de regeling vast en maak hem bekend.`,tags:['klokkenluider','melden','integriteit'],bron:'Wet bescherming klokkenluiders'},
 {id:'cpx-142',thema:'compliance',vraag:'Moet ik een gedragscode voor medewerkers hebben?',antwoord:`Een gedragscode maakt integriteitsnormen concreet. Denk aan omgang met geschenken, nevenfuncties, vertrouwelijkheid en privé-transacties. De wet noemt geen vast format. Laat medewerkers de code tekenen en bespreek hem periodiek.`,tags:['gedragscode','integriteit','medewerkers'],bron:'Wft'},
 {id:'cpx-143',thema:'compliance',vraag:'Mag een medewerker een nevenfunctie hebben?',antwoord:`Dat kan, maar het kan leiden tot belangenconflicten. Laat nevenfuncties melden en vooraf beoordelen. Leg vast welke nevenfuncties zijn toegestaan en onder welke voorwaarden. Evalueer bij wijzigingen.`,tags:['nevenfunctie','belangenconflict','integriteit'],bron:'Wft'},
 {id:'cpx-144',thema:'compliance',vraag:'Hoe ga ik om met een klant die familie is van een medewerker?',antwoord:`Dit kan een belangenconflict opleveren. Laat bij voorkeur een andere adviseur het advies geven of controleren. Leg de situatie en de maatregelen vast. Zorg dat het advies even zorgvuldig is als bij andere klanten.`,tags:['belangenconflict','familie','onafhankelijkheid'],bron:'Wft'},
 {id:'cpx-145',thema:'compliance',vraag:'Mag ik zelf bemiddelen bij de verkoop van een woning en ook de hypotheek adviseren?',antwoord:`Dat kan, maar het geeft een duidelijk belangenconflict. U hebt belang bij de verkoop en bij een zo hoog mogelijke financiering. Informeer de klant hierover en leg uit hoe u het conflict beheerst. Leg de informatie en maatregelen vast.`,tags:['belangenconflict','makelaardij','hypotheek'],bron:'Wft'},
 {id:'cpx-146',thema:'compliance',vraag:'Wat is een register van belangenconflicten?',antwoord:`Een register geeft overzicht van mogelijke belangenconflicten en de maatregelen daartegen. Denk aan samenwerkingen, aandeelhouderschap van aanbieders en beloningsafspraken. Actualiseer het register bij wijzigingen. Het ondersteunt uw integriteitsbeleid en SIRA.`,tags:['belangenconflict','register','integriteit'],bron:'Wft'},
 {id:'cpx-147',thema:'compliance',vraag:'Mag een geldverstrekker aandeelhouder zijn van mijn adviesbedrijf?',antwoord:`Dat is niet verboden, maar het raakt de onafhankelijkheid. U moet de klant informeren over deze relatie. U mag uzelf dan in de regel niet onafhankelijk noemen. Beoordeel en beheers het belangenconflict.`,tags:['aandeelhouder','onafhankelijkheid','belangenconflict'],bron:'Wft'},
 {id:'cpx-148',thema:'compliance',vraag:'Moet ik een klant informeren over een financieel belang bij een aanbieder?',antwoord:`Ja. Een klant moet weten welke banden u hebt met aanbieders als die het advies kunnen beïnvloeden. Vermeld dit in uw informatie vooraf. Leg vast dat de klant deze informatie heeft gekregen.`,tags:['financieel belang','informatieplicht','aanbieder'],bron:'Wft'},
 {id:'cpx-149',thema:'compliance',vraag:'Wat is het risico van een volmachtrelatie met een verzekeraar?',antwoord:`Als gevolmachtigde handelt u namens de verzekeraar bij acceptatie en schade. Tegelijk adviseert u de klant. Dat kan een belangenconflict geven. Informeer de klant en zorg voor heldere scheiding van taken.`,tags:['volmacht','verzekeraar','belangenconflict'],bron:'Wft'},
 {id:'cpx-150',thema:'compliance',vraag:'Moet ik vastleggen waarom ik een signaal niet heb gemeld?',antwoord:`Ja, dat is verstandig. Beschrijf het signaal, het onderzoek dat u deed en waarom u concludeerde dat er geen ongebruikelijke transactie was. Zo toont u aan dat u zorgvuldig hebt gewogen. Bewaar deze vastlegging vertrouwelijk, gescheiden van het klantdossier.`,tags:['melding','afweging','vastlegging'],bron:'Wwft'},
 {id:'cpx-151',thema:'compliance',vraag:'Op welke grondslag verwerk ik klantgegevens voor een adviestraject?',antwoord:`Meestal is de grondslag de uitvoering van een overeenkomst met de klant. Voor gegevens die een wet voorschrijft, zoals de Wwft, is de grondslag een wettelijke verplichting. Toestemming is vaak niet de beste grondslag, omdat die kan worden ingetrokken. Leg per verwerking de grondslag vast.`,tags:['AVG','grondslag','klantgegevens'],bron:'AVG'},
 {id:'cpx-152',thema:'compliance',vraag:'Mag ik een klant adviseren die tegelijk een traject bij een andere adviseur heeft?',antwoord:`Ja. De klant is vrij om meerdere adviseurs te raadplegen. Vraag wel naar lopende aanvragen, omdat dubbele aanvragen tot verwarring of afwijzing kunnen leiden. Maak duidelijk wat uw rol is. Leg vast wat de klant hierover vertelde.`,tags:['meerdere adviseurs','aanvragen','rolverdeling'],bron:'Wft'},
 {id:'cpx-153',thema:'compliance',vraag:'Mag ik het BSN van een klant vastleggen?',antwoord:`Het BSN mag u alleen verwerken als een wet dat toestaat. Zonder wettelijke grondslag schermt u het BSN af, bijvoorbeeld op een kopie van het identiteitsbewijs. Controleer of uw verwerking een wettelijke basis heeft. Leg uw werkwijze vast.`,tags:['BSN','identiteitsbewijs','AVG'],bron:'Uitvoeringswet AVG'},
 {id:'cpx-154',thema:'compliance',vraag:'Wat moet in een verwerkersovereenkomst staan?',antwoord:`In een verwerkersovereenkomst legt u vast welke gegevens de verwerker verwerkt, voor welk doel en hoe hij die beveiligt. Ook staan er afspraken in over geheimhouding, subverwerkers, datalekken en het einde van de samenwerking. Sluit zo een overeenkomst met bijvoorbeeld uw CRM-leverancier. Bewaar de overeenkomsten centraal.`,tags:['verwerkersovereenkomst','leverancier','AVG'],bron:'AVG'},
 {id:'cpx-155',thema:'compliance',vraag:'Is een geldverstrekker mijn verwerker?',antwoord:`Meestal niet. Een geldverstrekker of verzekeraar bepaalt zelf doel en middelen van de verwerking en is dan zelf verwerkingsverantwoordelijke. Een verwerkersovereenkomst is dan niet nodig. Wel moet u de klant informeren aan wie u gegevens verstrekt.`,tags:['verwerker','verwerkingsverantwoordelijke','geldverstrekker'],bron:'AVG'},
 {id:'cpx-156',thema:'compliance',vraag:'Wat is het verschil tussen een beveiligingsincident en een datalek?',antwoord:`Een beveiligingsincident is elke gebeurtenis die de beveiliging raakt, zoals een phishingmail of een storing. Een datalek is een incident waarbij persoonsgegevens verloren gaan, worden ingezien of worden gewijzigd zonder dat dat mag. Niet elk incident is dus een datalek. Registreer beide en beoordeel per incident of persoonsgegevens zijn geraakt.`,tags:['beveiligingsincident','datalek','registratie'],bron:'AVG'},
 {id:'cpx-157',thema:'compliance',vraag:'Wat betekent de zorgplicht na het afsluiten van een product?',antwoord:`De zorgplicht stopt niet altijd bij het afsluiten. Als u nazorg hebt afgesproken, moet u die ook leveren. Ook zonder afspraak kan het nodig zijn om een klant te informeren over belangrijke wijzigingen die u bekend zijn. Leg vast welke nazorg u hebt afgesproken en geleverd.`,tags:['zorgplicht','nazorg','afspraken'],bron:'Wft'},
 {id:'cpx-158',thema:'compliance',vraag:'Binnen welke termijn beantwoord ik een inzageverzoek?',antwoord:`U reageert zonder onredelijke vertraging en uiterlijk binnen een maand. In bijzondere gevallen mag u de termijn verlengen, met tijdige motivering aan de klant. Verifieer eerst de identiteit van de verzoeker. Leg het verzoek en de afhandeling vast.`,tags:['inzageverzoek','termijn','AVG'],bron:'AVG'},
 {id:'cpx-159',thema:'compliance',vraag:'Moet ik mijn interne aantekeningen meegeven bij een inzageverzoek?',antwoord:`Persoonsgegevens in interne aantekeningen vallen in beginsel onder het inzagerecht. Persoonlijke gedachten van medewerkers kunnen soms worden uitgezonderd. Schrijf aantekeningen daarom altijd zakelijk en respectvol. Twijfelt u, vraag juridisch advies.`,tags:['inzage','aantekeningen','AVG'],bron:'AVG'},
 {id:'cpx-160',thema:'compliance',vraag:'Mag ik een klantdossier verwijderen op verzoek van de klant?',antwoord:`Niet altijd. Wettelijke bewaarplichten en uw belang bij bewijs kunnen verwijdering in de weg staan. Leg uit welke gegevens u moet bewaren en waarom. Verwijder wat niet meer nodig is en leg de afhandeling vast.`,tags:['verwijderen','bewaarplicht','AVG'],bron:'AVG'},
 {id:'cpx-161',thema:'compliance',vraag:'Wat is een register van verwerkingsactiviteiten?',antwoord:`Het register beschrijft welke persoonsgegevens u verwerkt, voor welk doel, op welke grondslag en met wie u ze deelt. Ook bewaartermijnen en beveiliging staan erin. Bijna elk adviesbedrijf moet een register hebben, omdat het regelmatig gegevens verwerkt. Houd het actueel.`,tags:['verwerkingsregister','AVG','documentatie'],bron:'AVG'},
 {id:'cpx-162',thema:'compliance',vraag:'Wanneer is een DPIA nodig?',antwoord:`Een DPIA is nodig bij een verwerking met een waarschijnlijk hoog privacyrisico. Denk aan grootschalige profilering of nieuwe technologie zoals AI-tools met klantgegevens. De Autoriteit Persoonsgegevens publiceert een lijst met verwerkingen waarvoor een DPIA verplicht is. Leg de uitkomst en maatregelen vast.`,tags:['DPIA','privacyrisico','AI'],bron:'AVG'},
 {id:'cpx-163',thema:'compliance',vraag:'Mag ik klantgegevens via WhatsApp ontvangen?',antwoord:`Wees terughoudend. Berichtenapps zijn vaak niet ingericht op veilige opslag en bewaartermijnen. Gegevens komen ook op privételefoons terecht. Gebruik bij voorkeur een beveiligd klantportaal en leg uw beleid vast.`,tags:['WhatsApp','beveiliging','AVG'],bron:'AVG'},
 {id:'cpx-164',thema:'compliance',vraag:'Hoe beveilig ik e-mail met klantgegevens?',antwoord:`Gebruik versleuteling of een beveiligd portaal voor gevoelige stukken. Stuur geen kopieën van identiteitsbewijzen of loonstroken via gewone e-mail. Zorg voor tweestapsverificatie op mailaccounts. Leg de maatregelen vast in uw beveiligingsbeleid.`,tags:['e-mail','beveiliging','versleuteling'],bron:'AVG'},
 {id:'cpx-165',thema:'compliance',vraag:'Mag ik klantgegevens gebruiken voor marketing?',antwoord:`Alleen als daarvoor een geldige grondslag is. Voor elektronische marketing aan bestaande klanten gelden aparte regels. Bied altijd een eenvoudige afmeldmogelijkheid. Gebruik dossiergegevens niet zomaar voor andere doeleinden.`,tags:['marketing','AVG','doelbinding'],bron:'AVG'},
 {id:'cpx-166',thema:'compliance',vraag:'Moet ik een functionaris gegevensbescherming aanstellen?',antwoord:`Voor de meeste kleine adviesbedrijven is dat niet verplicht. Verplicht is het onder meer bij grootschalige verwerking van bijzondere gegevens of grootschalige monitoring. Wel moet iemand intern de AVG-naleving bewaken. Leg uw afweging vast.`,tags:['FG','AVG','organisatie'],bron:'AVG'},
 {id:'cpx-167',thema:'compliance',vraag:'Wat doe ik als een laptop met klantgegevens wordt gestolen?',antwoord:`Behandel het als een mogelijk datalek. Beoordeel of de laptop versleuteld was en of gegevens op afstand kunnen worden gewist. Meld zo nodig binnen 72 uur bij de Autoriteit Persoonsgegevens. Doe ook aangifte en registreer het incident.`,tags:['diefstal','datalek','versleuteling'],bron:'AVG'},
 {id:'cpx-168',thema:'compliance',vraag:'Mag ik klantgegevens delen met een collega-kantoor voor een second opinion?',antwoord:`Alleen als daarvoor een grondslag is en de klant op de hoogte is. Deel zo min mogelijk en bij voorkeur geanonimiseerd. Maak afspraken over vertrouwelijkheid. Leg vast wat u hebt gedeeld en waarom.`,tags:['second opinion','delen','AVG'],bron:'AVG'},
 {id:'cpx-169',thema:'compliance',vraag:'Wat is het verschil tussen een klacht en een geschil?',antwoord:`Een klacht is een uiting van ontevredenheid van een klant. Een geschil ontstaat als de klacht na interne behandeling niet is opgelost. Pas dan kan de klant naar Kifid. Behandel elke klacht serieus, ook als die informeel binnenkomt.`,tags:['klacht','geschil','Kifid'],bron:'Kifid'},
 {id:'cpx-170',thema:'compliance',vraag:'Wat moet in mijn interne klachtenprocedure staan?',antwoord:`Beschrijf hoe een klant een klacht kan indienen, wie de klacht behandelt en binnen welke termijn u reageert. Vermeld de mogelijkheid om daarna naar Kifid te gaan. Registreer klachten en gebruik ze om uw dienstverlening te verbeteren. Maak de procedure bekend aan klanten.`,tags:['klachtenprocedure','intern','Kifid'],bron:'Wft'},
 {id:'cpx-171',thema:'compliance',vraag:'Mag ik een klant adviseren die in het buitenland woont?',antwoord:`Dat kan, maar controleer of uw vergunning en de regels van het woonland dit toelaten. Let op extra Wwft-risicos en op fiscale gevolgen van het woonland. Geldverstrekkers en verzekeraars hebben vaak aparte acceptatieregels. Leg uw beoordeling vast.`,tags:['buitenland','vergunning','Wwft'],bron:'Wft'},
 {id:'cpx-172',thema:'compliance',vraag:'Hoe beoordeelt Kifid of een advies zorgvuldig was?',antwoord:`Kifid kijkt naar wat een redelijk bekwaam en redelijk handelend adviseur in die situatie had moeten doen. Daarbij is het dossier van groot belang. Wat niet is vastgelegd, is moeilijk te bewijzen. Kifid toetst aan de regels en normen die golden op het moment van advies.`,tags:['Kifid','zorgvuldigheid','maatstaf'],bron:'Kifid'},
 {id:'cpx-173',thema:'compliance',vraag:'Wat is eigen schuld bij een Kifid-uitspraak?',antwoord:`Kifid kan oordelen dat de klant zelf ook heeft bijgedragen aan de schade. Bijvoorbeeld door informatie niet te lezen of onjuiste gegevens te geven. De schadevergoeding wordt dan verminderd. Een goed dossier helpt om dit aan te tonen.`,tags:['eigen schuld','Kifid','schadevergoeding'],bron:'Kifid'},
 {id:'cpx-174',thema:'compliance',vraag:'Hoe berekent Kifid de schade bij een fout in een advies?',antwoord:`Kifid vergelijkt de situatie na de fout met de situatie als er correct was geadviseerd. Het verschil is de schade. Voorbeeld: kreeg een klant een te hoge rente door een verkeerde rentevaste periode, dan kan het renteverschil de basis zijn. Ook voordelen voor de klant kunnen worden verrekend.`,tags:['schadeberekening','Kifid','rekenvoorbeeld'],bron:'Kifid'},
 {id:'cpx-175',thema:'compliance',vraag:'Wanneer verjaart een claim van een klant wegens slecht advies?',antwoord:`Een vordering tot schadevergoeding verjaart in de regel vijf jaar nadat de klant bekend werd met de schade en de aansprakelijke partij. Er geldt daarnaast een lange absolute termijn na de schadeveroorzakende gebeurtenis. De verjaring kan worden gestuit. Bewaar dossiers daarom lang genoeg.`,tags:['verjaring','claim','aansprakelijkheid'],bron:'Burgerlijk Wetboek'},
 {id:'cpx-176',thema:'compliance',vraag:'Kan ik zelf een geschil voorleggen aan Kifid?',antwoord:`De klachtprocedure bij Kifid is in principe bedoeld voor consumenten en bepaalde kleine zakelijke klanten. Een financiële onderneming start normaal geen procedure als klager. Bij een geschil over betaling kunt u naar de rechter. Raadpleeg het reglement van Kifid.`,tags:['Kifid','onderneming','reglement'],bron:'Kifid'},
 {id:'cpx-177',thema:'compliance',vraag:'Wat is een collectieve of terugkerende klacht?',antwoord:`Als meerdere klanten over hetzelfde onderwerp klagen, kan er een structureel probleem zijn. Analyseer de oorzaak en kijk of andere klanten ook geraakt zijn. Overweeg een proactieve oplossing voor die groep. Leg de analyse en maatregelen vast.`,tags:['klachtenanalyse','structureel','herstel'],bron:'Wft'},
 {id:'cpx-178',thema:'compliance',vraag:'Hoe ga ik om met een klacht over de hoogte van mijn factuur?',antwoord:`Vergelijk de factuur met de vooraf gemaakte afspraken. Leg uit hoe de kosten zijn opgebouwd. Is de afspraak onduidelijk, dan kan dat in het nadeel van de adviseur uitvallen. Zorg daarom altijd voor heldere schriftelijke kostenafspraken.`,tags:['factuur','kosten','klacht'],bron:'Kifid'},
 {id:'cpx-179',thema:'compliance',vraag:'Hoe ga ik om met een tolk in het adviesgesprek?',antwoord:`Een tolk kan nodig zijn om passend te adviseren. Leg vast wie heeft getolkt en wat de relatie met de klant is. Let op dat de tolk geen eigen belang heeft, zoals een familielid dat meetekent. Controleer met eenvoudige vragen of de klant de kern begrijpt.`,tags:['tolk','begrijpelijkheid','belangenconflict'],bron:'Wft'},
 {id:'cpx-180',thema:'compliance',vraag:'Wat is een normoverdragende brief van de AFM?',antwoord:`Met een normoverdragende brief geeft de AFM aan dat een onderneming een norm heeft overtreden en wat zij verwacht. Het is een informele maatregel zonder boete. De AFM kan er later naar verwijzen als de overtreding doorgaat. Leg de opvolging aantoonbaar vast.`,tags:['AFM','normoverdragend','maatregel'],bron:'AFM'},
 {id:'cpx-181',thema:'compliance',vraag:'Welke formele maatregelen kan de AFM opleggen?',antwoord:`De AFM kan onder meer:
- een aanwijzing geven
- een last onder dwangsom opleggen
- een bestuurlijke boete opleggen
- een maatregel openbaar maken
- de vergunning intrekken
Welke maatregel volgt, hangt af van ernst en verwijtbaarheid.`,tags:['AFM','handhaving','maatregelen'],bron:'Wft'},
 {id:'cpx-182',thema:'compliance',vraag:'Maakt de AFM boetes openbaar?',antwoord:`Ja, in veel gevallen publiceert de AFM opgelegde boetes en lasten onder dwangsom. Dat kan reputatieschade geven. Bij bezwaar kan in sommige gevallen uitstel van publicatie worden gevraagd. Controleer de actuele publicatieregels.`,tags:['AFM','openbaarmaking','reputatie'],bron:'Wft'},
 {id:'cpx-183',thema:'compliance',vraag:'Wat doe ik bij een onaangekondigd bezoek van de AFM?',antwoord:`Werk mee, want medewerking is verplicht. Vraag naar de legitimatie en het doel van het onderzoek. Wijs een aanspreekpunt aan en noteer welke stukken worden ingezien of meegenomen. Overleg zo nodig met een juridisch adviseur.`,tags:['AFM','onderzoek','medewerking'],bron:'AFM'},
 {id:'cpx-184',thema:'compliance',vraag:'Mag ik weigeren stukken aan de AFM te geven?',antwoord:`Er geldt een medewerkingsplicht. De AFM mag inzage vorderen in zakelijke gegevens en documenten. Weigeren kan zelf een overtreding zijn. Bij twijfel over vertrouwelijke stukken overlegt u met de AFM en een jurist.`,tags:['AFM','medewerkingsplicht','documenten'],bron:'Awb'},
 {id:'cpx-185',thema:'compliance',vraag:'Wat is een themaonderzoek van de AFM?',antwoord:`Bij een themaonderzoek onderzoekt de AFM een onderwerp bij een groep ondernemingen. Denk aan dossierkwaliteit of kosten van advies. De uitkomsten worden vaak gepubliceerd met goede en slechte voorbeelden. Gebruik deze publicaties om uw eigen proces te toetsen.`,tags:['AFM','themaonderzoek','praktijk'],bron:'AFM'},
 {id:'cpx-186',thema:'compliance',vraag:'Hoe gebruik ik AFM-publicaties in mijn compliancebeleid?',antwoord:`Lees de publicaties en vertaal ze naar concrete acties. Vergelijk uw werkwijze met de genoemde goede en slechte voorbeelden. Leg vast wat u hebt aangepast. Zo toont u aan dat u de normen actief volgt.`,tags:['AFM','publicaties','compliancebeleid'],bron:'AFM'},
 {id:'cpx-187',thema:'compliance',vraag:'Wat is de AFM-heffing?',antwoord:`Ondernemingen onder toezicht betalen jaarlijks een bijdrage aan de kosten van het toezicht. De hoogte hangt af van de categorie en de omvang van de onderneming. De bedragen worden periodiek vastgesteld. Raadpleeg de AFM voor de actuele heffing.`,tags:['AFM','heffing','kosten'],bron:'AFM'},
 {id:'cpx-188',thema:'compliance',vraag:'Kan ik bezwaar maken tegen een AFM-besluit?',antwoord:`Ja. Tegen een besluit van de AFM staat bezwaar open. Daarna kunt u in beroep gaan bij de rechter. Let op de wettelijke termijnen. Laat u bijstaan door een jurist met ervaring in financieel toezichtrecht.`,tags:['bezwaar','AFM','beroep'],bron:'Awb'},
 {id:'cpx-189',thema:'compliance',vraag:'Wat is het verschil tussen AFM en DNB voor een adviseur?',antwoord:`De AFM houdt toezicht op het gedrag van financiële ondernemingen, zoals advies en informatie. DNB houdt prudentieel toezicht op onder meer banken en verzekeraars. Voor de meeste adviesbedrijven is de AFM de directe toezichthouder. DNB is vooral relevant via de partijen waarmee u samenwerkt.`,tags:['AFM','DNB','toezicht'],bron:'Wft'},
 {id:'cpx-190',thema:'compliance',vraag:'Wat is de Autoriteit Consument en Markt voor een adviseur?',antwoord:`De ACM houdt toezicht op mededinging en consumentenregels zoals oneerlijke handelspraktijken. Zij werkt samen met de AFM. Voor financiële diensten is de AFM meestal leidend. Let wel op regels voor reclame en prijsafspraken.`,tags:['ACM','mededinging','consumentenregels'],bron:'ACM'},
 {id:'cpx-191',thema:'compliance',vraag:'Welke eisen gelden voor reclame over financiële producten?',antwoord:`Reclame moet correct, duidelijk en niet misleidend zijn. Voor sommige producten gelden extra eisen, zoals een risicowaarschuwing bij krediet. Vermeld geen voordelen zonder de belangrijkste nadelen. Leg goedgekeurde uitingen en de toets vast.`,tags:['reclame','misleiding','informatie'],bron:'Wft'},
 {id:'cpx-192',thema:'compliance',vraag:'Mag ik op social media adviseren?',antwoord:`Algemene informatie mag. Zodra u een persoonlijke aanbeveling doet aan iemand, is er sprake van advies met alle eisen. Wees ook alert op misleidende of onvolledige berichten. Leg een socialmediabeleid vast voor medewerkers.`,tags:['social media','advies','reclame'],bron:'Wft'},
 {id:'cpx-193',thema:'compliance',vraag:'Mag ik reviews van klanten op mijn website plaatsen?',antwoord:`Ja, als ze echt zijn en u niet selecteert op een misleidende manier. Vraag toestemming aan de klant. Bewerk de inhoud niet. Plaats nooit nepreviews.`,tags:['reviews','website','misleiding'],bron:'ACM'},
 {id:'cpx-194',thema:'compliance',vraag:'Wat moet op mijn website staan?',antwoord:`Denk aan uw bedrijfsgegevens, AFM-registratie, Kifid-aansluiting, klachtenprocedure en privacyverklaring. Ook informatie over uw dienstverlening en kosten hoort er goed vindbaar te staan. Controleer regelmatig of alles actueel is. Leg vast wanneer de site is gecontroleerd.`,tags:['website','informatieplicht','transparantie'],bron:'Wft'},
 {id:'cpx-195',thema:'compliance',vraag:'Wat is het risico van leadgeneratie via een derde partij?',antwoord:`De derde partij kan reclame maken of klanten informeren op een manier die niet voldoet aan de regels. U kunt daarop worden aangesproken. Maak afspraken over de inhoud en toets de uitingen. Controleer of de partij niet zelf advies of bemiddeling doet zonder vergunning.`,tags:['leadgeneratie','derden','reclame'],bron:'Wft'},
 {id:'cpx-196',thema:'compliance',vraag:'Mag ik een aanbrengvergoeding betalen aan een makelaar?',antwoord:`Bij producten onder het provisieverbod kan dit problemen geven, omdat de klant uiteindelijk betaalt. Ook kan het een belangenconflict geven. Toets de afspraak aan de regels en informeer de klant. Leg de afspraak schriftelijk vast.`,tags:['aanbrengvergoeding','makelaar','belangenconflict'],bron:'Wft'},
 {id:'cpx-197',thema:'compliance',vraag:'Hoe ga ik om met een verzoek van de AFM om een dossier binnen korte tijd aan te leveren?',antwoord:`Lever het dossier zoals het is. Vul het niet achteraf aan zonder dat duidelijk te maken. Licht zo nodig in een begeleidende brief toe wat er aan het dossier ontbreekt. Overleg bij een korte termijn tijdig met de AFM.`,tags:['AFM','dossier','aanleveren'],bron:'AFM'},
 {id:'cpx-198',thema:'compliance',vraag:'Hoe toets ik of de klant het adviesrapport heeft begrepen?',antwoord:`Bespreek het rapport mondeling en stel open vragen over de belangrijkste keuzes en risicos. Laat de klant de gevolgen in eigen woorden samenvatten. Vul onduidelijkheden aan in het gesprek. Leg de bespreking en de vragen van de klant vast.`,tags:['begrijpelijkheid','adviesrapport','toetsing'],bron:'Wft'},
 {id:'cpx-199',thema:'compliance',vraag:'Wat is een veelgemaakte fout bij het beantwoorden van een AFM-vragenlijst?',antwoord:`Een fout is antwoorden geven die niet overeenkomen met de feitelijke praktijk. Ook ontbreekt vaak onderbouwing. Laat de antwoorden controleren door een tweede persoon. Bewaar de ingestuurde versie en de onderbouwing.`,tags:['AFM','vragenlijst','fouten'],bron:'AFM'},
 {id:'cpx-200',thema:'compliance',vraag:'Hoe ga ik om met een klacht die via een recensiesite binnenkomt?',antwoord:`Behandel een publieke klacht net zo serieus als een klacht via de normale route. Reageer kort en zakelijk en nodig de klant uit om de klacht buiten de site te bespreken. Deel geen klantgegevens in een openbare reactie. Registreer de klacht in uw klachtenregister.`,tags:['klacht','recensie','AVG'],bron:'Wft'},
 {id:'cpx-201',thema:'compliance',vraag:'Wat is AI-geletterdheid onder de AI-verordening?',antwoord:`Organisaties die AI-systemen gebruiken, moeten zorgen voor voldoende AI-kennis bij medewerkers die ermee werken. Die verplichting geldt al sinds begin 2025. Het niveau hangt af van de taak en het risico van het systeem. Leg trainingen en instructies vast.`,tags:['AI-geletterdheid','training','AI-verordening'],bron:'AI-verordening'},
 {id:'cpx-202',thema:'compliance',vraag:'Welke AI-toepassingen in de financiële sector zijn hoog risico?',antwoord:`De AI-verordening noemt onder meer AI voor de beoordeling van de kredietwaardigheid van natuurlijke personen. Ook AI voor risicobeoordeling en prijsstelling bij levens- en ziektekostenverzekeringen valt eronder. AI uitsluitend voor fraudedetectie is uitgezonderd van de kredietcategorie. Controleer de actuele lijst en toepassingsdata.`,tags:['hoog risico','kredietwaardigheid','AI-verordening'],bron:'AI-verordening'},
 {id:'cpx-203',thema:'compliance',vraag:'Ben ik aanbieder of gebruiksverantwoordelijke van een AI-systeem?',antwoord:`De aanbieder ontwikkelt het systeem of brengt het onder eigen naam op de markt. De gebruiksverantwoordelijke zet het systeem in onder eigen verantwoordelijkheid. Een adviesbedrijf dat een bestaand pakket gebruikt, is meestal gebruiksverantwoordelijke. Pas het systeem wezenlijk aan, dan kunt u aanbieder worden.`,tags:['aanbieder','gebruiksverantwoordelijke','rollen'],bron:'AI-verordening'},
 {id:'cpx-204',thema:'compliance',vraag:'Welke plichten heb ik als gebruiksverantwoordelijke van hoog-risico AI?',antwoord:`U gebruikt het systeem volgens de gebruiksinstructies. U zorgt voor menselijk toezicht door bekwame personen. U bewaart automatisch gegenereerde logs voor zover die onder uw controle staan. Ook informeert u betrokkenen in de gevallen die de verordening noemt.`,tags:['gebruiksverantwoordelijke','hoog risico','menselijk toezicht'],bron:'AI-verordening'},
 {id:'cpx-205',thema:'compliance',vraag:'Moet ik melden dat een klant met een chatbot praat?',antwoord:`Ja. De AI-verordening verplicht transparantie als mensen met een AI-systeem communiceren, tenzij dat al duidelijk is. Vermeld duidelijk dat het om een geautomatiseerde assistent gaat. Bied een route naar een menselijke adviseur. Controleer de toepassingsdatum van deze verplichting.`,tags:['chatbot','transparantie','AI-verordening'],bron:'AI-verordening'},
 {id:'cpx-206',thema:'compliance',vraag:'Mag ik een AI-tool een adviesrapport laten schrijven?',antwoord:`Als hulpmiddel kan dat, maar u blijft verantwoordelijk voor de inhoud. Controleer elke tekst op juistheid en op aansluiting bij het klantprofiel. Let op verzonnen feiten en verouderde regels. Leg vast dat een adviseur het rapport inhoudelijk heeft beoordeeld.`,tags:['AI','adviesrapport','controle'],bron:'Wft'},
 {id:'cpx-207',thema:'compliance',vraag:'Hoe leg ik het gebruik van AI vast in mijn bedrijfsvoering?',antwoord:`Maak een overzicht van alle AI-toepassingen, het doel en het risiconiveau. Beschrijf wie de toepassing beheert en hoe u controleert. Neem AI op in uw SIRA en AVG-documentatie. Evalueer periodiek of het gebruik nog passend is.`,tags:['AI-register','bedrijfsvoering','SIRA'],bron:'AI-verordening'},
 {id:'cpx-208',thema:'compliance',vraag:'Is een rekentool voor maximale hypotheek een AI-systeem?',antwoord:`Een rekentool met vaste regels die u zelf hebt ingesteld, is meestal geen AI-systeem in de zin van de verordening. Een systeem dat zelfstandig afleidt en voorspelt uit data, kan dat wel zijn. Beoordeel per tool de werking. Leg uw beoordeling vast.`,tags:['rekentool','AI-definitie','hypotheek'],bron:'AI-verordening'},
 {id:'cpx-209',thema:'compliance',vraag:'Welke verboden AI-praktijken zijn relevant voor adviseurs?',antwoord:`Verboden zijn onder meer AI-systemen die mensen manipuleren of misbruik maken van kwetsbaarheden zoals leeftijd of financiële situatie. Ook bepaalde vormen van sociale scoring zijn verboden. Deze verboden gelden al sinds begin 2025. Toets nieuwe marketing- en adviestools hierop.`,tags:['verboden praktijken','manipulatie','AI-verordening'],bron:'AI-verordening'},
 {id:'cpx-210',thema:'compliance',vraag:'Wie houdt toezicht op AI bij financiële ondernemingen?',antwoord:`In Nederland is de rol van de toezichthouders nog in ontwikkeling. Voor de financiële sector ligt een rol bij de bestaande financiële toezichthouders voor de hand. Daarnaast speelt de Autoriteit Persoonsgegevens een rol bij algoritmes en privacy. Volg de actuele berichtgeving van AFM en AP.`,tags:['toezicht','AI','AFM'],bron:'AI-verordening'},
 {id:'cpx-211',thema:'compliance',vraag:'Mag ik AI gebruiken om klantgesprekken samen te vatten?',antwoord:`Dat kan, mits u de AVG naleeft. Informeer de klant en zorg voor een passende grondslag en verwerkersafspraken. Controleer de samenvatting voordat die in het dossier komt. Bewaar opnames niet langer dan nodig.`,tags:['AI','gespreksverslag','AVG'],bron:'AVG'},
 {id:'cpx-212',thema:'compliance',vraag:'Wat is het risico van AI bij het beoordelen van klantdocumenten?',antwoord:`AI kan fouten maken bij het lezen van loonstroken of bankafschriften. Ook kan het bias bevatten. Laat uitkomsten altijd controleren door een medewerker. Leg vast welke controles zijn uitgevoerd.`,tags:['AI','documentcontrole','bias'],bron:'AI-verordening'},
 {id:'cpx-213',thema:'compliance',vraag:'Wat vraagt de Leidraad Hypotheekadvisering 2026 rond het klantprofiel?',antwoord:`De Leidraad legt nadruk op een volledig beeld van de huidige en toekomstige situatie. Denk aan inkomen, vermogen, verplichtingen, plannen en de woning zelf. Het klantprofiel moet zichtbaar doorwerken in het advies. Raadpleeg de Leidraad voor de concrete verwachtingen.`,tags:['Leidraad','klantprofiel','hypotheek'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-214',thema:'compliance',vraag:'Hoe neem ik de staat van de woning mee in het advies?',antwoord:`De woning zelf beïnvloedt de risicos en de lasten. Denk aan onderhoud, energielabel en mogelijke funderingsproblemen. Bespreek de gevolgen voor de woonlasten en de waarde. Leg vast wat bekend was en wat is besproken.`,tags:['woning','onderhoud','risicoanalyse'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-215',thema:'compliance',vraag:'Wat is het risico van een vaste adviesvolgorde in software?',antwoord:`Software kan standaardkeuzes voorstellen die niet bij de klant passen. Adviseurs nemen die dan soms ongemerkt over. Controleer of elke keuze in het advies bewust is gemaakt. Leg vast waarom u een standaardinstelling hebt gevolgd of aangepast.`,tags:['software','standaardkeuzes','controle'],bron:'Wft'},
 {id:'cpx-216',thema:'compliance',vraag:'Is een second opinion een adviesdienst onder de Wft?',antwoord:`Als u een persoonlijke aanbeveling doet over een financieel product, is er sprake van advies. Dan gelden de Wft-eisen, zoals een passend klantprofiel. Maak vooraf afspraken over de omvang van de second opinion. Leg vast welke stukken u hebt beoordeeld en wat uw conclusie is.`,tags:['second opinion','advies','afbakening'],bron:'Wft'},
 {id:'cpx-217',thema:'compliance',vraag:'Rekenvoorbeeld: hoe toon ik in het dossier het effect van het wegvallen van een tweede inkomen?',antwoord:`In de leennormen 2026 telt het tweede inkomen volledig mee. Bereken daarom ook de woonlasten als alleen het hoogste inkomen overblijft. Toon in bedragen het tekort per maand en hoe lang de buffer dat kan opvangen. Leg het scenario, de besproken oplossingen en de keuze van de klant vast.`,tags:['tweede inkomen','rekenvoorbeeld','risicoanalyse'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-218',thema:'compliance',vraag:'Mag ik klantgegevens aan de notaris verstrekken?',antwoord:`Voor de uitvoering van de transactie is dat meestal nodig en toegestaan. Verstrek alleen de gegevens die de notaris nodig heeft. Gebruik een veilige verzendmethode. Informeer de klant in uw privacyverklaring over deze verstrekking.`,tags:['notaris','gegevensverstrekking','AVG'],bron:'AVG'},
 {id:'cpx-219',thema:'compliance',vraag:'Wat doe ik bij een datalek bij mijn softwareleverancier?',antwoord:`De leverancier is als verwerker verplicht u zonder onredelijke vertraging te informeren. U bent als verwerkingsverantwoordelijke verantwoordelijk voor de beoordeling en een eventuele melding. Vraag direct welke gegevens en klanten zijn geraakt. Leg de communicatie en uw afweging vast.`,tags:['datalek','verwerker','leverancier'],bron:'AVG'},
 {id:'cpx-220',thema:'compliance',vraag:'Rekenvoorbeeld: tot wanneer bewaar ik Wwft-gegevens van een beëindigde klantrelatie?',antwoord:`De bewaartermijn is vijf jaar na het einde van de zakelijke relatie. Eindigt de relatie bijvoorbeeld op 1 juni van een jaar, dan bewaart u de gegevens tot 1 juni vijf jaar later. Leg de einddatum van de relatie vast, zodat de termijn te bepalen is. Gebruik bij voorkeur een systeem dat de vernietigingsdatum signaleert.`,tags:['bewaartermijn','rekenvoorbeeld','Wwft'],bron:'Wwft'},
 {id:'cpx-221',thema:'compliance',vraag:'Wat doe ik als een klant om gegevensoverdraagbaarheid vraagt?',antwoord:`De klant kan onder voorwaarden vragen om zijn gegevens in een gangbaar digitaal formaat. Het gaat om gegevens die de klant zelf heeft aangeleverd en die u verwerkt op basis van toestemming of overeenkomst. Verifieer de identiteit van de klant. Reageer binnen de termijn die de AVG stelt.`,tags:['dataportabiliteit','rechten','AVG'],bron:'AVG'},
 {id:'cpx-222',thema:'compliance',vraag:'Hoe lang mag ik gegevens van een prospect bewaren?',antwoord:`Bewaar gegevens van iemand die geen klant werd niet langer dan nodig. Leg in uw privacybeleid een redelijke termijn vast. Wwft-gegevens kunnen een eigen bewaartermijn hebben. Verwijder of anonimiseer de rest na afloop.`,tags:['prospect','bewaartermijn','AVG'],bron:'AVG'},
 {id:'cpx-223',thema:'compliance',vraag:'Rekenvoorbeeld: hoe bereken ik de meldtermijn van een datalek?',antwoord:`De termijn van 72 uur loopt vanaf het moment dat u het datalek ontdekt. Ontdekt u een lek op maandag om 10.00 uur, dan meldt u uiterlijk donderdag om 10.00 uur. Weekenden en feestdagen tellen mee. Hebt u nog niet alle informatie, meld dan tijdig en vul later aan.`,tags:['datalek','meldtermijn','rekenvoorbeeld'],bron:'AVG'},
 {id:'cpx-224',thema:'compliance',vraag:'Wat doe ik bij een phishingaanval op mijn kantoor?',antwoord:`Wijzig direct de wachtwoorden van getroffen accounts en sluit toegang af. Onderzoek of klantgegevens zijn ingezien of verstuurd. Beoordeel of er een datalek is dat u moet melden. Registreer het incident en train medewerkers opnieuw.`,tags:['phishing','incident','beveiliging'],bron:'AVG'},
 {id:'cpx-225',thema:'compliance',vraag:'Rekenvoorbeeld: wanneer moet een inzageverzoek uiterlijk zijn beantwoord?',antwoord:`U reageert uiterlijk binnen een maand na ontvangst. Ontvangt u het verzoek op 15 maart, dan reageert u uiterlijk op 15 april. Wilt u verlengen, informeer de klant dan binnen die eerste maand met een motivering. Leg de ontvangstdatum en de reactiedatum vast.`,tags:['inzageverzoek','termijn','rekenvoorbeeld'],bron:'AVG'},
 {id:'cpx-226',thema:'compliance',vraag:'Wat doe ik als een klant dreigt met publiciteit?',antwoord:`Blijf zakelijk en behandel de klacht inhoudelijk. Reageer niet publiekelijk met klantgegevens. Bied de klant de normale klachtroute en de mogelijkheid van Kifid. Leg het contact en uw reactie vast.`,tags:['publiciteit','klacht','reputatie'],bron:'Kifid'},
 {id:'cpx-227',thema:'compliance',vraag:'Hoe behandel ik een klacht over een vertrokken medewerker?',antwoord:`De onderneming blijft verantwoordelijk voor het advies. Behandel de klacht op basis van het dossier. Vraag zo nodig een toelichting aan de oud-medewerker als dat mogelijk is. Leg de behandeling vast en meld de klacht zo nodig bij uw verzekeraar.`,tags:['klacht','oud-medewerker','verantwoordelijkheid'],bron:'Wft'},
 {id:'cpx-228',thema:'compliance',vraag:'Wat doet de AFM met een melding van een consument?',antwoord:`De AFM behandelt geen individuele klachten. Meldingen van consumenten gebruikt de AFM als signaal voor haar toezicht. Een melding kan aanleiding zijn voor nader onderzoek. Voor een individuele oplossing verwijst de AFM naar de klachtenprocedure en Kifid.`,tags:['AFM','signalen','consument'],bron:'AFM'},
 {id:'cpx-229',thema:'compliance',vraag:'Hoe bepaalt de AFM de hoogte van een bestuurlijke boete?',antwoord:`De wet kent boetecategorieën met een basisbedrag. De AFM kan de boete verhogen of verlagen op basis van ernst, duur en verwijtbaarheid van de overtreding. Ook de financiële draagkracht van de onderneming kan meewegen. Raadpleeg de Wft en de actuele boetebeleidsregels.`,tags:['bestuurlijke boete','AFM','handhaving'],bron:'Wft'},
 {id:'cpx-230',thema:'compliance',vraag:'Moet ik bij oversluiten de fiscale status van leningdelen controleren?',antwoord:`Ja. Oversluiten kan gevolgen hebben voor overgangsrecht en aflossingseis. Controleer per leningdeel de fiscale status en de historie. Fouten hier leiden tot verlies van renteaftrek. Leg de controle en de bron van de gegevens vast.`,tags:['oversluiten','fiscale status','overgangsrecht'],bron:'Wet IB 2001'},
 {id:'cpx-231',thema:'compliance',vraag:'Wat is het vier-ogenprincipe en wanneer pas ik het toe?',antwoord:`Bij het vier-ogenprincipe controleert een tweede persoon belangrijk werk. Pas het toe bij complexe adviezen, afwijkend advies en werk van medewerkers onder begeleiding. Ook bij een klein kantoor kunt u een collega of externe partij inschakelen. Leg vast wie heeft gecontroleerd.`,tags:['vier-ogenprincipe','kwaliteitscontrole','dossier'],bron:'AFM'},
 {id:'cpx-232',thema:'compliance',vraag:'Wat is een veelgemaakte fout bij verduurzamingsadvies?',antwoord:`Een veelgemaakte fout is alleen de extra leenruimte noemen zonder te kijken naar de besparing en de kosten. Ook wordt soms niet gecontroleerd of de maatregel bij de woning past. Bespreek terugverdientijd en onderhoud. Leg de afweging vast.`,tags:['verduurzaming','fouten','advies'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-233',thema:'compliance',vraag:'Wat doe ik als een aanbieder een product wijzigt na mijn advies?',antwoord:`Beoordeel of de wijziging gevolgen heeft voor de passendheid bij uw klanten. Informeer betrokken klanten als de wijziging belangrijk is en u nazorg hebt afgesproken. Bied zo nodig een nieuw adviesgesprek aan. Leg vast welke klanten u hebt benaderd.`,tags:['productwijziging','nazorg','aanbieder'],bron:'Wft'},
 {id:'cpx-234',thema:'compliance',vraag:'Hoe ga ik om met een klant die vraagt om een hoger inkomen op te geven?',antwoord:`Werk daar niet aan mee. Het opgeven van onjuiste gegevens is fraude en in strijd met uw zorgplicht. Leg het verzoek en uw weigering vast. Beoordeel of u de dienstverlening beëindigt en of een melding nodig is.`,tags:['fraude','inkomen','integriteit'],bron:'Wft'},
 {id:'cpx-235',thema:'compliance',vraag:'Wat leg ik vast als de klant tegen mijn advies in een korte rentevaste periode kiest?',antwoord:`Leg uw advies vast en de reden van de klant voor de kortere periode. Laat in een rekenvoorbeeld zien wat de maandlast wordt bij een hogere rente na afloop. Noteer of de klant die hogere last kan dragen. Laat de klant bevestigen dat hij de afweging begrijpt.`,tags:['rentevaste periode','afwijkend','rekenvoorbeeld'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-236',thema:'compliance',vraag:'Mag ik als adviseur betrokken zijn bij de taxatie van de woning?',antwoord:`De taxateur moet onafhankelijk zijn van adviseur, koper en verkoper. Geef geen sturing op de waarde. Volg de regels van de geldverstrekker en het taxatie-instituut voor de opdrachtverlening. Leg vast hoe de taxatieopdracht is verstrekt.`,tags:['taxatie','onafhankelijkheid','belangenconflict'],bron:'NWWI'},
 {id:'cpx-237',thema:'compliance',vraag:'Hoe borg ik dat medewerkers nieuwe regels kennen?',antwoord:`Wijs iemand aan die nieuwe regels en publicaties volgt. Bespreek wijzigingen in een vast werkoverleg. Vertaal ze naar aanpassingen in werkinstructies en software. Leg vast wanneer wat is besproken.`,tags:['kennisborging','regelgeving','medewerkers'],bron:'Wft'},
 {id:'cpx-238',thema:'compliance',vraag:'Wat doe ik als een medewerker heeft geadviseerd zonder geldig diploma?',antwoord:`Stop direct met het zelfstandig adviseren door die medewerker. Laat de gegeven adviezen controleren door een vakbekwame adviseur. Herstel waar klanten nadeel hebben. Leg de analyse en maatregelen vast en beoordeel of melding aan de AFM nodig is.`,tags:['vakbekwaamheid','diploma','herstel'],bron:'Wft'},
 {id:'cpx-239',thema:'compliance',vraag:'Mag ik een explain-situatie zelf voorstellen aan de geldverstrekker?',antwoord:`Ja, u kunt de situatie van de klant toelichten en aangeven waarom een afwijking verantwoord is. De beslissing ligt bij de geldverstrekker. Onderbouw met stukken, zoals een werkgeversverklaring over een toekomstig inkomen. Leg de onderbouwing en de uitkomst vast.`,tags:['explain','geldverstrekker','onderbouwing'],bron:'Tijdelijke regeling hypothecair krediet'},
 {id:'cpx-240',thema:'compliance',vraag:'Hoe ga ik om met een verzoek van de politie om klantgegevens?',antwoord:`Verstrek alleen gegevens als daarvoor een wettelijke grondslag is, zoals een vordering van een bevoegde officier. Vraag om een schriftelijk verzoek en controleer de bevoegdheid. Verstrek niet meer dan gevraagd. Leg het verzoek en de verstrekking vast.`,tags:['politie','gegevensverstrekking','AVG'],bron:'AVG'},
 {id:'cpx-241',thema:'compliance',vraag:'Mag ik een NHG-hypotheek adviseren zonder de NHG-voorwaarden te bespreken?',antwoord:`Nee. Bespreek de voorwaarden, de kosten van de borgtochtprovisie en de bescherming bij restschuld. Gebruik voor de kostengrens het actuele bedrag (zie NHG). Leg vast dat de voorwaarden zijn besproken. Controleer de actuele NHG-normen.`,tags:['NHG','voorwaarden','kostengrens'],bron:'NHG'},
 {id:'cpx-242',thema:'compliance',vraag:'Wat leg ik vast als de klant de energielabel-leenruimte volledig wil benutten?',antwoord:`De extra leenruimte is een maximum, geen advies. Toets of de hogere lasten passen bij het budget van de klant, ook als de verwachte besparing tegenvalt. Bespreek waar het extra bedrag voor wordt gebruikt. Leg de afweging en de keuze van de klant vast.`,tags:['energielabel','leenruimte','betaalbaarheid'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-243',thema:'compliance',vraag:'Hoe ga ik om met een klant die extra wil lenen voor verduurzaming zonder concrete plannen?',antwoord:`Vraag naar de maatregelen, de kosten en de planning. Leg uit dat de geldverstrekker vaak eisen stelt aan de besteding van het bedrag. Zonder concrete plannen is het risico groot dat de lening niet doelmatig wordt gebruikt. Leg het gesprek en uw advies vast.`,tags:['verduurzaming','bestedingsdoel','zorgplicht'],bron:'AFM Leidraad Hypotheekadvisering 2026'},
 {id:'cpx-244',thema:'compliance',vraag:'Hoe ga ik om met een klant die een aanbod wil tekenen zonder het te lezen?',antwoord:`Wijs de klant op de belangrijkste voorwaarden, kosten en risicos. Bespreek de kern van het aanbod kort mondeling. Bied tijd om het aanbod rustig te lezen. Leg vast wat u hebt toegelicht en dat de klant ervoor koos direct te tekenen.`,tags:['aanbod','ondertekening','zorgplicht'],bron:'Wft'},
 {id:'cpx-245',thema:'compliance',vraag:'Wie is verantwoordelijk bij werken onder een franchiseformule?',antwoord:`De onderneming met de vergunning is verantwoordelijk voor de naleving. Bij een franchiseformule kan elke vestiging een eigen vergunning hebben. Leg duidelijk vast wie welke taken uitvoert, zoals compliance en dossiertoetsing. Ga niet ervan uit dat de formule alles regelt.`,tags:['franchise','verantwoordelijkheid','vergunning'],bron:'Wft'},
 {id:'cpx-246',thema:'compliance',vraag:'Mag ik als adviseur zelf geld lenen aan een klant?',antwoord:`Doe dit niet. Kredietverlening aan consumenten vraagt een eigen vergunning. Het geeft bovendien een groot belangenconflict met uw adviesrol. Leg in uw integriteitsbeleid vast dat dit niet is toegestaan.`,tags:['kredietverlening','belangenconflict','integriteit'],bron:'Wft'},
 {id:'cpx-247',thema:'compliance',vraag:'Hoe toon ik aan dat mijn rekentool actuele normen gebruikt?',antwoord:`Controleer na elke update welke versie van de leennormen en fiscale regels de tool gebruikt. Leg de versie vast in het dossier of in de berekening. Vergelijk steekproefsgewijs met de uitkomst van de geldverstrekker. Meld afwijkingen aan de leverancier.`,tags:['rekentool','leennormen','versiebeheer'],bron:'Wft'},
 {id:'cpx-248',thema:'compliance',vraag:'Rekenvoorbeeld: hoe maak ik een uurtarief vooraf inzichtelijk?',antwoord:`Geef bij een uurtarief een inschatting van het aantal uren, bijvoorbeeld 12 tot 15 uur voor een standaard hypotheektraject. Vermenigvuldig dat met het uurtarief en noem de bandbreedte van de totale kosten. Spreek af dat u de klant informeert als de inschatting wordt overschreden. Leg de afspraak schriftelijk vast.`,tags:['uurtarief','kosten','rekenvoorbeeld'],bron:'Wft'},
 {id:'cpx-249',thema:'compliance',vraag:'Moet ik bij AI-ondersteund advies uitleggen hoe de uitkomst tot stand kwam?',antwoord:`De klant moet het advies kunnen begrijpen, ook als AI is gebruikt. U moet de uitkomst zelf kunnen uitleggen en onderbouwen. Een verwijzing naar de tool is geen motivering. Leg de inhoudelijke onderbouwing vast in het dossier.`,tags:['AI','uitlegbaarheid','motivering'],bron:'AI-verordening'},
 {id:'cpx-250',thema:'compliance',vraag:'Hoe leg ik vast dat een klant bewust kiest voor een hogere hypotheek dan geadviseerd?',antwoord:`Beschrijf het geadviseerde bedrag en het bedrag dat de klant kiest. Toon de gevolgen voor de maandlasten en de vrije ruimte in bedragen. Leg de motivering van de klant en de besproken risicos vast. Blijf binnen de leennormen en de acceptatieregels van de geldverstrekker.`,tags:['hogere hypotheek','afwijkend','vastlegging'],bron:'AFM Leidraad Hypotheekadvisering 2026'}
]);
